-- Combined 019 + 020: run this one file, once, in the Supabase SQL editor. Safe to re-run.

-- 019: R32 becomes its own model; new and renamed R32 guides; Mk5 GTI FSI turbo kit guide
-- Run in the Supabase SQL editor after 018. Safe to re-run.

-- 1. R32 model under Volkswagen, listed right after the GTI
insert into models (id,brand_id,name,live,sort) values ('r32','vw','R32',true,1) on conflict (id) do update set name=excluded.name, live=excluded.live, sort=excluded.sort;
update models set sort=0 where id='gti'; update models set sort=2 where id='golf'; update models set sort=3 where id='jetta'; update models set sort=4 where id='passat';

-- 2. R32 generations (US model years)
insert into generations (id,model_id,name,year_from,year_to,live,sort) values ('r32-mk4','r32','Mk4',2004,2004,false,0) on conflict (id) do update set name=excluded.name, year_from=excluded.year_from, year_to=excluded.year_to, live=excluded.live, sort=excluded.sort;
insert into generations (id,model_id,name,year_from,year_to,live,sort) values ('r32-mk5','r32','Mk5',2008,2008,true,1) on conflict (id) do update set name=excluded.name, year_from=excluded.year_from, year_to=excluded.year_to, live=excluded.live, sort=excluded.sort;

-- 3. Move the 3.2 VR6 (BUB) out of the GTI Mk5 list; its tasks follow it automatically
update powertrains set model_id='r32', generation_id='r32-mk5', name='3.2 VR6', code='BUB', note='2008 · DSG · 4Motion all-wheel drive' where id='bub';

-- 4. Title convention: (R32) suffix on R32-only guides that have a GTI counterpart
update tasks set title='Coolant pipe & thermostat housing (R32)' where id='coolant-pipe-r32';
update tasks set title='Crankcase breather / PCV (R32)' where id='pcv-r32';
update tasks set title='Timing chain guides & tensioner (R32)' where id='timing-chain-r32';
update guides set content = jsonb_set(content,'{title}','"Timing chain guides & tensioner (R32)"') where id='timing-chain-r32';

-- 5. Exhaust stub split into headers and cat-back; the combined stub goes away
delete from guides where id='exhaust-r32';
delete from tasks where id='exhaust-r32';
insert into tasks (id,powertrain_id,guide_id,title,category,group_name,aliases,live,time_label,difficulty) values ('headers-r32','bub','headers-r32','Exhaust headers (R32)','Engine','exhaust',array['headers','exhaust manifold','header','exhaust']::text[],false,'4–6 hr',4) on conflict (id) do update set powertrain_id=excluded.powertrain_id, guide_id=excluded.guide_id, title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into guides (id,content) values ('headers-r32',$j${"id": "headers-r32", "title": "Exhaust headers (R32)", "fits": "2008 VW R32 · 3.2 VR6 (BUB) · DSG · 4Motion", "heroId": "haldex-hero", "alsoFits": "Mk5 R32 (3.2 VR6 BUB)", "category": "Engine", "kind": "upgrade", "glance": {"timeFirst": "4–6 hr", "timeRepeat": "—", "difficulty": 4, "cost": "—", "risk": "—", "why": "The VR6's cast manifolds feed a single downpipe. Tubular headers (HPA, Eurojet, SPM and others) open the top of the rev range and sharpen the sound, but they live against the firewall on a 4Motion car and the job is mostly access: heat shields, the downpipe flange and the O2 sensors.", "note": "The hardest of the R32 exhaust jobs. Difficulty 3–4: access behind the engine, rusted studs, sensor threads."}, "heroCap": "Placeholder illustration.", "lifespan": {"title": "When to expect it", "headline": ["Cat-back is the classic R32 mod. Difficulty 2–3."], "earliest": null, "detail": "The R32's exhaust is its own system: a single downpipe from the VR6 manifolds, a resonated mid-section and the centre-exit twin-tip rear. Milltek, HPA and Eurojet make cat-backs; headers and high-flow downpipes exist for the sound and a few horsepower.", "factors": [], "inspect": [], "confidence": {"level": "community", "n": 2, "note": "Stub; sourcing pending"}}, "should": {"yesIf": [], "codes": [], "notes": ["This guide is a placeholder so the job is on the map for R32 owners; the full procedure, part options and torque values are being sourced."], "confidence": {"level": "community", "n": 1, "note": "Stub"}}, "parts": [], "aftermarket": [], "tools": [], "before": [], "steps": [{"n": 1, "title": "Coming soon", "blocks": [{"t": "text", "b": "Full procedure pending. The summary above is accurate; use it to decide urgency."}]}], "alsoReplace": [], "check": {"tab": "Notes", "title": "What we know so far", "illId": "haldex-hero", "illCap": "", "rows": [], "c": {"level": "community", "n": 1, "note": "Stub"}}, "aftercare": [], "disagreements": [], "sources": ["R32 owner forums; ECS R32 article"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into tasks (id,powertrain_id,guide_id,title,category,group_name,aliases,live,time_label,difficulty) values ('catback-r32','bub','catback-r32','Cat-back exhaust (R32)','Engine','exhaust',array['cat-back','catback','exhaust','muffler','milltek']::text[],false,'2–3 hr',2) on conflict (id) do update set powertrain_id=excluded.powertrain_id, guide_id=excluded.guide_id, title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into guides (id,content) values ('catback-r32',$j${"id": "catback-r32", "title": "Cat-back exhaust (R32)", "fits": "2008 VW R32 · 3.2 VR6 (BUB) · DSG · 4Motion", "heroId": "haldex-hero", "alsoFits": "Mk5 R32 (3.2 VR6 BUB)", "category": "Engine", "kind": "upgrade", "glance": {"timeFirst": "2–3 hr", "timeRepeat": "—", "difficulty": 2, "cost": "—", "risk": "—", "why": "The R32's exhaust is its own system: resonated mid-section and the centre-exit twin-tip rear. Milltek, HPA, Eurojet and others make cat-backs that bolt to the factory cat flange; the classic R32 mod for the sound alone.", "note": "Bolt-on. Difficulty 2: stiff hangers and one rusty flange."}, "heroCap": "Placeholder illustration.", "lifespan": {"title": "When to expect it", "headline": ["Cat-back is the classic R32 mod. Difficulty 2–3."], "earliest": null, "detail": "The R32's exhaust is its own system: a single downpipe from the VR6 manifolds, a resonated mid-section and the centre-exit twin-tip rear. Milltek, HPA and Eurojet make cat-backs; headers and high-flow downpipes exist for the sound and a few horsepower.", "factors": [], "inspect": [], "confidence": {"level": "community", "n": 2, "note": "Stub; sourcing pending"}}, "should": {"yesIf": [], "codes": [], "notes": ["This guide is a placeholder so the job is on the map for R32 owners; the full procedure, part options and torque values are being sourced."], "confidence": {"level": "community", "n": 1, "note": "Stub"}}, "parts": [], "aftermarket": [], "tools": [], "before": [], "steps": [{"n": 1, "title": "Coming soon", "blocks": [{"t": "text", "b": "Full procedure pending. The summary above is accurate; use it to decide urgency."}]}], "alsoReplace": [], "check": {"tab": "Notes", "title": "What we know so far", "illId": "haldex-hero", "illCap": "", "rows": [], "c": {"level": "community", "n": 1, "note": "Stub"}}, "aftercare": [], "disagreements": [], "sources": ["R32 owner forums; ECS R32 article"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();

-- 6. Finished R32 guides (live)
insert into tasks (id,powertrain_id,guide_id,title,category,group_name,aliases,live,time_label,difficulty) values ('coolant-pipe-r32','bub','coolant-pipe-r32','Coolant pipe & thermostat housing (R32)','Engine',null,array['P0128','coolant flange','coolant leak','coolant pipe','crack pipe','crackpipe','thermostat','thermostat housing']::text[],true,'4–6 hr',3) on conflict (id) do update set powertrain_id=excluded.powertrain_id, guide_id=excluded.guide_id, title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into guides (id,content) values ('coolant-pipe-r32',$j${"id": "coolant-pipe-r32", "title": "Coolant pipe & thermostat housing (R32)", "fits": "2008 VW R32 · 3.2 VR6 (BUB) · DSG · 4Motion", "heroId": "coolant-pipe-hero", "alsoFits": "Every 24v/3.2 VR6 (Mk4 R32, A3 3.2, TT 3.2, Eos 3.2) shares the parts; access steps here are Mk5 R32 specific", "category": "Engine", "kind": "repair", "variants": null, "glance": {"timeFirst": "4–6 hr", "timeRepeat": "3 hr", "difficulty": 3, "cost": "$130–260 parts · $30 coolant", "risk": "Coolant everywhere · cracking the new plastic housing by tightening unevenly · the pipe won't come out until the SAI pump is gone", "why": "A plastic pipe runs along the front of the VR6 from the water pump to the thermostat housing, under the intake manifold. Owners call it the crack pipe for a reason: the pipe, the housing and every o-ring between them go brittle and weep. Coolant smell, a level that keeps dropping and pink crust on the front of the block are the signs. Replace pipe, housing, thermostat and all seals together; do it once with an aluminium pipe.", "note": "Procedure from 24v owner write-ups plus Mk5 R32 owners' access notes; two torque values trace to the factory manual via forum posts."}, "heroCap": "The pipe seats in the water pump socket on the left and the thermostat housing slides onto its other end. Three o-rings, two long bolts, and a secondary air pump sitting right in front of it all.", "lifespan": {"title": "When to expect it", "headline": ["Weeping housing or pipe seals by 80,000–120,000 miles, or simply by age"], "earliest": "Whenever the front of the block shows pink crust", "detail": "Heat cycles harden the o-rings and embrittle the plastic. One Mk5 owner's original housing was still sound at fifteen years but every seal in it leaked. A cracked pipe dumps coolant fast; a seeping housing just smells sweet for a year first.", "factors": ["Age more than mileage", "Track use and repeated hot idling", "Oil dripping on the plastic from a valve cover or filter housing leak"], "inspect": ["Flashlight down the front of the block at every oil change: pink or white crust under the housing or along the pipe", "Coolant level on a cold engine; a slow drop with no puddle means a seep that dries on the hot block"], "confidence": {"level": "community", "n": 4, "note": "Owner reports on Mk4/Mk5 24v cars agree on the pattern; no factory interval exists."}}, "should": {"yesIf": ["Pink crust on the front of the block below the intake manifold", "Coolant smell after a drive, level dropping, no puddle", "Thermostat stuck (slow warm-up, or temp gauge climbing) and the housing is original", "Radiator or water pump already coming out: the pipe is a cheap add"], "codes": ["P0128", "P2181"], "notes": ["Pipe: 022 121 050 (also listed 022 121 085). Aluminium versions from ECS, URO, GruvenParts, 42 Draft. Housing: 022 121 117 C. Cover: 022 121 121 E. Thermostat: 022 121 113.", "Buy the full seal set with the parts: two pipe o-rings (N 101 392 01), the housing-to-head o-ring (021 121 119 A), thermostat o-ring (N 901 368 02). Old seals are the reason 'new' housings leak.", "The radiator's lower corner is the other classic Mk5 R32 leak and it leaks as the car cools. Find the wet spot before you buy anything."], "confidence": {"level": "high", "n": 4, "note": "Part numbers agree across vendor listings and owner threads; Mk5-specific access from R32 owners."}}, "parts": [{"tier": "oe", "name": "Coolant pipe (crack pipe)", "pn": "022 121 050", "note": "Plastic OE; see aluminium options below", "price": "$40–60", "links": []}, {"tier": "oe", "name": "Thermostat housing", "pn": "022 121 117 C", "note": "Genuine or Febi; skip the cheapest plastic", "price": "$50–185", "links": []}, {"tier": "oe", "name": "Thermostat housing cover", "pn": "022 121 121 E", "note": "3 × M6 bolts", "price": "$45", "links": []}, {"tier": "oe", "name": "Thermostat (3.2)", "pn": "022 121 113", "note": "Wahler / Genuine, with o-ring", "price": "$50–110", "links": []}, {"tier": "oe", "name": "Pipe o-rings ×2", "pn": "N 101 392 01", "note": "34.5 × 3.55", "price": "$4 each", "links": []}, {"tier": "oe", "name": "Housing-to-head o-ring", "pn": "021 121 119 A", "note": "", "price": "$5–9", "links": []}, {"tier": "oe", "name": "Thermostat o-ring", "pn": "N 901 368 02", "note": "Often boxed with the thermostat", "price": "$7", "links": []}, {"tier": "oe", "name": "Housing bolt kit", "pn": "3× M6×20 · 2× M6×120 · 1× M6×22", "note": "Optional; old bolts corrode", "price": "$10", "links": []}, {"tier": "oe", "name": "Coolant, G12++ or G13, two gallons premixed", "pn": "G 012 A8G / G 013 A8J", "note": "You won't drain it all; this leaves margin", "price": "$30", "links": []}, {"tier": "oe", "name": "Coolant temp sensor (optional)", "pn": "06A 919 501 A", "note": "Green top; cheap while the housing is off", "price": "$15–25", "links": []}], "aftermarket": [{"name": "ECS billet aluminium pipe", "note": "Machined, o-ring grooves sized for the OE seals, fits the plastic housing. Lifetime replacement.", "price": "$120–140", "signal": "Do it once", "links": []}, {"name": "URO aluminium pipe", "note": "Same idea at a third of the price; owners report years of leak-free use.", "price": "$40", "signal": "Value", "links": []}, {"name": "iABED / GruvenParts cast aluminium housing kit", "note": "Housing and cover in alloy with seals and bolts. One vendor notes the pipe may need trimming to fit its housing; buy pipe and housing as a matched kit.", "price": "$170–260", "signal": "Metal housing", "links": []}], "tools": [{"name": "5 mm and 6 mm hex on a long 3/8\" extension (the housing bolts are 120 mm deep); 10 mm and 13 mm sockets; T25/T30 Torx"}, {"name": "Hose-clamp pliers (spring clamps everywhere), slip-joint pliers, pick for old o-rings, mirror, flashlight"}, {"name": "Two big drain pans, towels, a funnel; torque wrench that reads 8–10 Nm"}, {"name": "Optional: T30 and 13 mm for the lock-carrier service position; a vacuum fill tool makes bleeding trivial"}], "before": ["Stone-cold engine. The system is pressurised hot and the plastic is brittle hot.", "Find the leak first: wash the front of the block, drive, look again. Pipe seeps run down the block; housing seeps pool at the head.", "Lay out the new seals against the old ones as they come out so nothing is missed. Every o-ring gets replaced; the housing is only as good as its seals.", "Photograph every hose and plug on the housing before you touch it."], "steps": [{"n": 1, "title": "Undertray, airbox, engine cover", "blocks": [{"t": "text", "b": "Splash pan off. Airbox and its inlet pipe out the way the R32 air filter guide shows (unplug the MAF first). Engine cover off. You're now looking at the intake manifold with the thermostat housing below it on the passenger side and the secondary air pump in front."}]}, {"n": 2, "title": "Drain the coolant", "blocks": [{"t": "text", "b": "Expansion tank cap off. Pan under the radiator's lower hose; release its spring clamp at the radiator and pull the hose. Let it run, then move the pan to the front of the block: every joint you open from here dribbles more."}, {"t": "note", "b": "You'll get most of it, not all of it. Keep the pan under the engine until the pipe is out."}]}, {"n": 3, "title": "Secondary air pump out", "blocks": [{"t": "text", "b": "Unplug the pump's connector and pull its outlet hose (spring clamp) and intake hose. Unbolt its bracket from the engine and lift the pump clear. On the Mk5 there is no way to get the pipe out with this in place."}, {"t": "ill", "id": "coolant-pipe-hero", "cap": "Pump out, and the pipe and housing are in front of you."}]}, {"n": 4, "title": "Optional: lock carrier forward", "blocks": [{"t": "text", "b": "If the pipe won't come out from below in step 7, or the radiator or water pump is coming out anyway, put the front end in service position: bumper cover off, the crash bar and radiator carrier unbolted and slid forward on long bolts. Mk5 R32 owners who did this say the whole job got easy; those who didn't, describe it in words we can't print."}]}, {"n": 5, "title": "Hoses and plug off the housing", "blocks": [{"t": "text", "b": "Upper radiator hose off the cover. Small hoses off the housing ports (heater feed, expansion tank return). The hose from the pipe's nipple to the oil cooler: release its spring clamp with slip-joint pliers; it's set at an awkward angle from the factory. Unplug the coolant temperature sensor and unclip the harness from the housing bracket."}]}, {"n": 6, "title": "Housing off", "blocks": [{"t": "text", "b": "Two long 5 mm hex bolts pass through the housing and its bracket into the block. Long extension, straight in, out they come. Break the housing loose, rock it off the pipe end and the head, and bring it out the top. Recover the o-ring from the head if it stayed behind."}]}, {"n": 7, "title": "Pipe out", "blocks": [{"t": "text", "b": "One M6 bolt holds the pipe's bracket to the block; remove it. The pipe is now held only by its o-ring in the water pump socket. From below, pull it back out of the socket (rotate it if it's stuck), then feed it up and out the top past the manifold. Clean both sockets of old o-ring and crust; a pick and a rag, not a screwdriver."}]}, {"n": 8, "title": "Build the housing on the bench", "blocks": [{"t": "text", "b": "Thermostat into the new housing with its new o-ring, spring toward the engine. Cover on with three M6 bolts. Fit the new housing-to-head o-ring dry in its groove; fit a new pipe o-ring on the housing's pipe socket. Move the temperature sensor (or fit a new one) with a new clip."}, {"t": "torque", "label": "Thermostat cover bolts (3× M6, 5 mm hex)", "nm": 8, "alt": [10], "c": {"level": "varies", "n": 2, "note": "8 Nm is the 24v figure quoted from the Bentley manual; 10 Nm is the 12v value. Plastic cover: use 8."}}]}, {"n": 9, "title": "Pipe in", "blocks": [{"t": "text", "b": "New o-ring on the pump end, wet with coolant. Feed the pipe down from the top and press it square into the water pump socket until it seats. Rotate it so the nipple points where the oil-cooler hose comes from and the bracket lines up with its hole. Leave the bracket bolt loose."}, {"t": "warn", "b": "An o-ring that rolls or pinches going in is a leak you'll only find after the intake is back on. If it doesn't slide in with light pressure, pull it and look."}]}, {"n": 10, "title": "Housing on, bolts walked in", "caution": true, "blocks": [{"t": "text", "b": "Slide the housing onto the pipe end and up against the head. Start both long bolts by hand, then take them down a turn at a time, alternating, until the housing is flat against the head. Only then torque. Uneven tightening rolls the head o-ring out of its groove or cracks the plastic; both mean doing this again."}, {"t": "torque", "label": "Housing to block (2× M6×120, 5 mm hex)", "nm": 10, "c": {"level": "medium", "n": 2, "note": "Factory-manual figure via two forum sources (12v and 24v); the same M6 into aluminium on this engine."}}, {"t": "torque", "label": "Pipe bracket bolt (M6)", "nm": 10, "c": {"level": "single", "n": 1, "note": "No figure found in the sources; standard M6-in-aluminium value."}}]}, {"n": 11, "title": "Hoses, sensor, pump, airbox", "blocks": [{"t": "text", "b": "Every hose back with a new spring clamp where the old one was tired. Sensor plugged, harness clipped. Secondary air pump and its hoses back on. Lower radiator hose on. Airbox, engine cover, and the lock carrier back if you moved it."}]}, {"n": 12, "title": "Fill, bleed, watch", "blocks": [{"t": "text", "b": "Heater on full hot, fan low. Fill the expansion tank with premixed G12++/G13 to the max mark, cap off. Start the engine and let it idle; squeeze the upper hose now and then. As the thermostat opens the level drops; keep topping. When the heater blows hot and the level holds, cap on and drive it, then recheck cold in the morning. A vacuum fill tool skips all of this."}, {"t": "note", "b": "Pink drips in the first hour usually mean a hose clamp, not a seal. Wipe everything dry before the drive so a fresh trace is obvious."}]}], "alsoReplace": [{"name": "Water pump", "why": "Same drain, same access once the lock carrier is forward, and it drives off the timing side. If it has never been done, do it now."}, {"name": "Coolant temperature sensor", "why": "It lives in the housing you're holding. The green-top sensor is cheap and the old one is the same age as the seals."}, {"name": "Lower radiator hose and heater hoses", "why": "They're off or in your hand anyway. Bubbling or soft rubber means silicone or new OE hoses."}, {"name": "Radiator lower corner check", "why": "The other common Mk5 R32 leak. Look while the bumper is off."}], "check": {"tab": "Where's the leak?", "title": "Where is the coolant going?", "illId": "coolant-pipe-hero", "illCap": "Pink crust marks the spot; gravity moves it down and back.", "rows": [{"see": "Crust on the head and top of the block under the housing", "means": "Housing seams or its head o-ring.", "do": "This guide. Pipe too while you're there."}, {"see": "Wet along the front of the block low down, or on the transmission side", "means": "Pipe o-rings or a cracked pipe.", "do": "This guide; aluminium pipe."}, {"see": "Puddle appears after the car cools, front centre", "means": "Radiator lower corner (classic Mk5 R32).", "do": "Radiator. Do the pipe while the front end is off."}, {"see": "Sweet smell, level drops, nothing visible", "means": "Seep that dries on the hot block, or the water pump.", "do": "Pressure test cold; UV dye finds it in one drive."}, {"see": "Slow warm-up, heater lukewarm, P0128", "means": "Thermostat stuck open.", "do": "Thermostat and housing together; the housing has to come off anyway."}], "c": {"level": "community", "n": 3, "note": "Leak locations from Mk5 R32 owner threads; pressure-test advice is standard practice."}}, "aftercare": ["Check the level cold for a week and look at the front of the block with a flashlight after the first hot drive.", "Clear any P0128/P2181 stored from a stuck thermostat and confirm the gauge sits at 90 °C.", "Keep the old pipe. Cut it open: the crack is usually at the nipple or the bracket ear, which tells you whether heat or vibration is your car's problem."], "disagreements": [{"topic": "How much to take apart on a Mk5", "pos": "Housing from the top only; SAI pump out and pipe from below; lock carrier forward; full front end and intake manifold off.", "call": "SAI pump out plus lock carrier in service position is the DIY path. Pull the manifold only if you have another reason to."}, {"topic": "Plastic or aluminium", "pos": "Alloy pipe is universal advice. Alloy housings divide owners: some fit fine, one vendor warns the pipe may need modification.", "call": "Alloy pipe with a genuine or Febi housing; or a matched alloy pipe-and-housing kit. Not the cheapest plastic housing."}, {"topic": "Delete the secondary air pump while it's out", "pos": "Common on forums for the space it frees.", "call": "It's an emissions device and disabling it sets a monitor fault. Put it back."}], "sources": ["ECS Tuning Mk5 R32 coolant flange and thermostat listings (part numbers, prices)", "VW Vortex 24v VR6 crack pipe and thermostat housing DIY (procedure; 8 Nm cover figure from Bentley)", "VW Vortex 12v VR6 thermostat housing DIY and factory torque list (10 Nm housing; even-tightening method)", "R32OC Mk5 R32 crack pipe, coolant leak and water pump threads (Mk5 access, radiator corner)", "GruvenParts and Wahler part listings (pipe and thermostat numbers)", "Humble Mechanic Mk4 R32 thermostat video"], "embeds": [{"id": "YqlTvk1qi2k", "note": "Humble Mechanic, 2004 R32 (Mk4). Same housing and pipe; his intake and air pump sit differently, so use steps 1–4 here for access and his video for the housing itself."}]}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into tasks (id,powertrain_id,guide_id,title,category,group_name,aliases,live,time_label,difficulty) values ('pcv-r32','bub','pcv-r32','Crankcase breather / PCV (R32)','Engine',null,array['P2279','breather','crankcase breather','oil consumption','oil separator','pcv','vacuum leak','valve cover','valve cover gasket']::text[],true,'4–5 hr',3) on conflict (id) do update set powertrain_id=excluded.powertrain_id, guide_id=excluded.guide_id, title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into guides (id,content) values ('pcv-r32',$j${"id": "pcv-r32", "title": "Crankcase breather / PCV (R32)", "fits": "2008 VW R32 · 3.2 VR6 (BUB) · DSG · 4Motion", "heroId": "pcv-r32-hero", "alsoFits": "3.2 BUB in the A3 8P, TT 8J and Eos; the 3.6 VR6 uses the same separator design", "category": "Engine", "kind": "repair", "variants": {"question": "Which fix?", "hint": "On this engine the PCV diaphragm lives inside the oil separator in the valve cover's hump, behind the oil cap. Getting to it means the intake manifold and valve cover come off. Once you're there you can fit a whole new separator or just the membrane. The third route is an upgrade: leave the dead valve where it is, seal its port, and put a serviceable valve in the breather hose so the next failure is a ten-minute job.", "options": [{"id": "oe", "label": "New oil separator (factory fix)", "when": "Cracked or brittle separator, oil sludge in the hump, or you want the box VW sells"}, {"id": "diaphragm", "label": "New diaphragm only", "when": "Separator body is sound; you're doing the valve cover gasket anyway and want the $30 fix"}, {"id": "external", "label": "External serviceable valve (upgrade)", "when": "You want the next failure to be a hose swap, and you're comfortable with a fit-check on the hose run"}]}, "glance": {"timeFirst": "4–5 hr", "timeRepeat": "3 hr", "difficulty": 3, "cost": "$135–220 (separator + gaskets) · $150 (diaphragm + gaskets) · $80–120 (external valve)", "risk": "Debris into open intake ports · cracking the cover by uneven torque · breather port left unsealed on the external route", "why": "The VR6 breathes through a cyclone oil separator moulded into the valve cover; a rubber diaphragm inside it meters crankcase vapour into the intake. When the diaphragm tears the engine has a permanent vacuum leak: hissing at idle, a fluctuating idle, lean codes, oil use, and enough crankcase pressure to push oil past the cover gasket and rear main seal. VW's answer is a $990 valve cover. The real answers cost $30–105 in parts and an afternoon with the intake manifold off.", "note": "Procedure from a vendor's documented job on a 2008 R32; upgrade route documented on the TT 3.2 and described by a vendor for the R32, not yet confirmed hands-on on a Mk5 hose run."}, "heroCap": "Separator hump behind the oil cap, five T20 screws, the diaphragm inside. The breather hose leaves the hump for the intake; the external valve goes in that hose.", "lifespan": {"title": "When to expect it", "headline": ["Diaphragm tears somewhere past 80,000 miles or ten years; earlier with oil-soaked rubber"], "earliest": "Any age if the oil was left too long and sludged the separator", "detail": "It's a rubber membrane flexing on every intake pulse. It doesn't wear out so much as age out. The tear is sudden: one day there's a whistle under the cover and the idle hunts.", "factors": ["Age of the rubber", "Extended oil intervals (sludge in the cyclone)", "Aftermarket intake changing the vacuum the valve sees"], "inspect": ["Oil-cap test at idle: light suction is normal; a cap that gets sucked down hard, or a hiss that stops when you cover the cap, is the diaphragm", "Fresh oil weep at the valve cover gasket or the rear of the engine that wasn't there last year"], "confidence": {"level": "community", "n": 3, "note": "Owner reports across BUB cars; no factory interval."}}, "should": {"yesIf": ["Hissing or whistling from under the engine cover at idle", "Idle hunts or stalls; lean or small-leak codes (P0171, P2279)", "Oil consumption up, oil at the valve cover gasket or bellhousing", "Doing the valve cover gasket anyway (same access; the separator is right there)"], "codes": ["P2279", "P0171", "P0507", "P0300"], "notes": ["Factory separator assembly: 022 103 515 B, about $105. Gasket kit for the cover, plug-tube seals and bolts: 022 103 483 EKT3 (Elring), about $115. The whole valve cover 022 103 429 AA is $990 and only worth it if the cover itself is cracked.", {"only": ["diaphragm"], "text": "RKX sells the membrane alone for the 3.2/3.6 separator (~$30). Same disassembly as the separator swap; you're saving the part cost, not the labour."}, {"only": ["external"], "text": "Genuine breather valve 022 103 765 A (the Touareg-style valve with the N79 heater plug) replaces the plain breather tube. The in-cover valve stays, its port gets sealed. Documented on the TT 3.2 and sold for the R32; do the fit-check in step 2 before you commit."}], "confidence": {"level": "high", "n": 4, "note": "Vendor DIY on a 2008 R32 plus vendor listings and owner threads agree on parts and location."}}, "parts": [{"tier": "oe", "name": "Oil separator (PCV housing)", "pn": "022 103 515 B", "note": "Sits in the cover under 5 T20 screws", "price": "$105", "links": [], "only": ["oe"]}, {"tier": "aftermarket", "name": "RKX PCV diaphragm, 3.2/3.6", "pn": "RKX v4.0", "note": "Membrane only", "price": "$30", "links": [], "only": ["diaphragm"]}, {"tier": "oe", "name": "Valve cover gasket kit", "pn": "022 103 483 EKT3", "note": "Gasket, plug-tube seals, bushings, bolts", "price": "$115", "links": [], "only": ["oe", "diaphragm"]}, {"tier": "oe", "name": "Intake manifold gasket", "pn": "confirm by VIN", "note": "Do not reuse the old one", "price": "$25–40", "links": [], "only": ["oe", "diaphragm"]}, {"tier": "oe", "name": "Oil-resistant RTV", "pn": "Permatex Ultra Black or equivalent", "note": "Two dabs at the timing-cover joints", "price": "$10", "links": [], "only": ["oe", "diaphragm"]}, {"tier": "oe", "name": "Breather valve, external", "pn": "022 103 765 A", "note": "Genuine; replaces plain tube 022 103 202", "price": "$80–110", "links": [], "only": ["external"]}, {"tier": "oe", "name": "Cap / plug for the cover's breather port", "pn": "sized to your port; see step 4", "note": "Silicone cap and clamp, or a threaded plug if the port is threaded", "price": "$5–10", "links": [], "only": ["external"]}], "aftermarket": [{"name": "External serviceable breather valve (022 103 765 A)", "note": "Not faster, just maintainable: a $90 valve you can change at the roadside instead of a manifold-off afternoon. The upgrade we'd choose. Fit-check required on the Mk5 hose run.", "price": "$80–110", "signal": "Serviceable", "links": []}, {"name": "Oil catch can (universal, baffled, 19 mm ports)", "note": "The BUB already has a cyclone separator and is port-injected and naturally aspirated, so there's little carbon to stop and little oil to catch. Worth it only on a boosted or track car. Buy one with baffles and a drain; empty it before winter or it freezes and pressurises the crankcase.", "price": "$60–200", "signal": "Track / boost only", "links": []}, {"name": "Genuine valve cover with valve, 022 103 429 AA", "note": "Only if the cover is cracked. Same labour as the separator.", "price": "$990", "signal": "Last resort", "links": []}], "tools": [{"name": "10 mm and 16 mm sockets; 5 mm and 6 mm hex bits (a long ball-end 6 mm for the manifold); 10 mm triple-square; T20, T25, T30", "only": ["oe", "diaphragm"]}, {"name": "Picks, flat screwdriver, razor blade, extensions, torque wrench that reads 10–13 Nm", "only": ["oe", "diaphragm"]}, {"name": "Hose-clamp pliers, a sharp knife for the hose, silicone cap or plug for the cover port", "only": ["external"]}, {"name": "Shop vacuum or compressed air to clear the intake ports before the manifold goes back", "only": ["oe", "diaphragm"]}], "before": [{"only": ["oe", "diaphragm"], "text": "Cold engine, clean bay. Six open intake ports will be staring at you for an hour; anything that drops in is a head-off job."}, {"only": ["oe", "diaphragm"], "text": "Lay the bolts out on tape in the order and position they came from; there are three sizes of fastener on the manifold brackets alone."}, "Confirm the diagnosis first: oil-cap test at idle, and listen for the hiss with the engine cover off. A leaking manifold gasket or intake boot gives the same codes.", {"only": ["external"], "text": "Look at your breather tube before ordering: it runs from the hump toward the intake tract with a heater connector on it. If yours has no connector or a different end fitting, the external valve is a different part number or a fabricated splice; stop and ask."}], "steps": [{"n": 1, "title": "Nose to service position", "only": ["oe", "diaphragm"], "blocks": [{"t": "text", "b": "Bumper cover off (T25 along the bottom and in the wheel wells, T20 grilles, side-marker plugs, washer hose). Two T30 behind each headlight, hood cable unclipped, then the eight 16 mm crash-beam bolts: top four out, bottom four nearly out. Tilt the top of the radiator support forward. The manifold needs this room to lift clear."}, {"t": "note", "b": "Same service position as the coolant pipe guide. If you've done one, you've done the other."}]}, {"n": 2, "title": "Fit-check the external valve", "only": ["external"], "blocks": [{"t": "text", "b": "Airbox and inlet pipe out. Follow the breather hose from the cover hump to where it joins the intake. Compare the new 022 103 765 A against it end for end: same length, same end fittings, same heater connector. If it matches, carry on. If not, don't cut anything; this is where the Touareg-tube analogy breaks and you need the OE route instead."}, {"t": "warn", "b": "The heater plug (N79) must be connected on the new valve or you'll trade a vacuum leak for a heater fault code, and the valve can freeze shut in winter."}]}, {"n": 3, "title": "Swap the hose and valve", "only": ["external"], "blocks": [{"t": "text", "b": "Release both hose ends and the heater connector. Fit the new valve assembly the same way round: the valve body toward the intake, arrow (if marked) pointing to the intake."}]}, {"n": 4, "title": "Seal the cover's own valve port", "only": ["external"], "caution": true, "blocks": [{"t": "text", "b": "The dead diaphragm inside the cover is now a hole to the intake. Its outlet on the hump must be capped: a silicone cap and clamp on a barb, or a plug in a threaded port. Left open, you have a bigger leak than you started with."}, {"t": "text", "b": "Start it. The hiss should be gone and the idle steady within a minute. Oil-cap test: gentle suction. Airbox back in."}]}, {"n": 5, "title": "Airbox, harness and hoses off the top", "only": ["oe", "diaphragm"], "blocks": [{"t": "text", "b": "MAF unplugged, intake tube off the throttle body, airbox out. Driver's side: the harness bracket on the head (10 mm nut and stud at the back, T30 at the front), three plugs at the throttle body, harness laid aside. Six coil connectors off, harness cover off. Walk the breather hose off the cover hump with a flat screwdriver."}]}, {"n": 6, "title": "Free the manifold", "only": ["oe", "diaphragm"], "blocks": [{"t": "text", "b": "Behind the manifold by feel: four vacuum lines off and one bracket (10 mm triple-square). Throttle body: four 5 mm hex bolts. Passenger side: fuel-line bracket (10 mm). Manifold side bolts (10 mm triple-square, one each side). The two brackets on the radiator face of the manifold for the dipstick tube and sensors: T30. Vacuum line off the variable-intake solenoid."}]}, {"n": 7, "title": "Manifold off", "only": ["oe", "diaphragm"], "blocks": [{"t": "text", "b": "Nine 6 mm hex bolts along the front of the manifold; the new gasket shows you every hole. Pry the six coils out of the head with a flat screwdriver. Rock the manifold forward to break the gasket, then lift it up and away. Cover the six ports with clean rag immediately."}, {"t": "ill", "id": "pcv-r32-hero", "cap": "With the manifold off, this is your view. Hump on the right behind the oil cap."}]}, {"n": 8, "title": "Valve cover off", "only": ["oe", "diaphragm"], "blocks": [{"t": "text", "b": "Eleven 10 mm bolts, outer ones first. Lift the cover off and take it to the bench. Peel the old gasket and the plug-tube seals. Razor the old RTV off the head where the timing cover meets it, wiping away from the open engine."}]}, {"n": 9, "title": "New separator into the cover", "only": ["oe"], "blocks": [{"t": "text", "b": "Five T20 screws hold the separator into the hump. Break its seal gently with a flat screwdriver and pop it out. Oil the gasket on the new one, press it home firmly and square, and run the five screws in snug. Plastic into plastic: no torque figure exists and none is needed."}]}, {"n": 9, "title": "New diaphragm into the separator", "only": ["diaphragm"], "blocks": [{"t": "text", "b": "Five T20 screws, separator out as above. Open the separator's cap (it's clipped or screwed depending on revision), lift out the torn membrane and its spring, and seat the new one the same way round with the spring under it. Close it and refit the separator with the five screws snug."}, {"t": "warn", "b": "Look at the separator body while it's open. Any crack in the cyclone or a warped sealing face and you're buying the assembly after all; a new membrane won't seal it."}]}, {"n": 10, "title": "Gaskets on, cover on, torque", "only": ["oe", "diaphragm"], "caution": true, "blocks": [{"t": "text", "b": "New cover gasket and six plug-tube seals into the cover. Two dabs of oil-resistant RTV where the timing cover meets the head, and at the two studs. New bolts in the cover. Set it down square and tighten in a crossing pattern from the middle out."}, {"t": "torque", "label": "Valve cover bolts (11× 10 mm)", "nm": 10, "c": {"level": "single", "n": 1, "note": "From a vendor's documented job on a 2008 R32. Light-alloy cover on a rubber gasket; do not exceed."}}]}, {"n": 11, "title": "Manifold and everything back", "only": ["oe", "diaphragm"], "blocks": [{"t": "text", "b": "New manifold gasket pressed into the manifold. Rags out of the ports, blow them clear. Manifold down, all nine bolts started by hand, then tightened middle-out. Coils in, harness over the manifold, brackets, throttle body (four 5 mm hex), vacuum lines, fuel bracket, breather hose onto the hump, driver's-side harness bracket, MAF and airbox. Nose back down: T30s behind the headlights, 16 mm beam bolts, bumper."}, {"t": "torque", "label": "Intake manifold bolts (9× 6 mm hex)", "nm": 13, "c": {"level": "single", "n": 1, "note": "Same vendor job on the 2008 R32."}}]}, {"n": 12, "title": "Start and listen", "only": ["oe", "diaphragm"], "blocks": [{"t": "text", "b": "No hiss, steady idle, oil-cap test shows gentle suction. Clear codes. Check for oil at the cover gasket after the first hot drive."}]}], "alsoReplace": [{"name": "Valve cover gasket and plug-tube seals", "why": "You're holding the cover. The seals are the same age as the diaphragm, and oil in the plug wells kills coils.", "only": ["oe", "diaphragm"]}, {"name": "Rear main seal check", "why": "If crankcase pressure has been high for a while, look for oil at the bellhousing. Fix the PCV first or a new seal blows too."}, {"name": "Intake manifold gasket", "why": "Never reuse; it's the difference between fixing a vacuum leak and creating one.", "only": ["oe", "diaphragm"]}, {"name": "Spark plugs and coils", "why": "Coils are out and the plugs are exposed; see the R32 plugs guide.", "only": ["oe", "diaphragm"]}], "check": {"tab": "Diagnose it", "title": "Is it really the PCV?", "illId": "pcv-r32-hero", "illCap": "Everything that hisses is not the diaphragm.", "rows": [{"see": "Hiss at idle from under the engine cover; oil cap sucked down hard", "means": "Torn diaphragm.", "do": "This guide."}, {"see": "Hiss that changes when you wiggle the intake boot or throttle body", "means": "Boot or manifold gasket leak.", "do": "Smoke test; gasket or boot, not the PCV."}, {"see": "Rough idle, lean codes, no noise, oil cap normal", "means": "Vacuum line off the back of the manifold, or an injector.", "do": "Check the four lines behind the manifold first."}, {"see": "P2279 with a heater-circuit code", "means": "N79 heater on the breather tube, not the diaphragm.", "do": "Tube/valve with heater; external route fixes both."}, {"see": "Oil at the bellhousing plus oil use", "means": "Crankcase pressure pushed the rear main seal.", "do": "PCV first, then the seal (transmission-out)."}], "c": {"level": "community", "n": 3, "note": "Symptom pattern from owner threads and the vendor DIY; smoke test is standard practice."}}, "aftercare": ["Idle should settle within a minute of the first start and stay steady; a hunt means a leak you created.", "Oil-cap test again after a week; the diaphragm is the one part here you can't see working.", {"only": ["oe", "diaphragm"], "text": "Watch the cover gasket for a month. Weeping means the RTV spots or a rolled gasket."}], "disagreements": [{"topic": "Separator, diaphragm, or whole cover", "pos": "VW sells only the cover ($990). Vendors sell the separator ($105). Owners fit a $30 membrane.", "call": "Separator if the body shows any age; membrane if it's clean and you're already there for a gasket. The cover only when it's cracked."}, {"topic": "External valve as a permanent fix", "pos": "Documented on the TT 3.2 with the Touareg-style valve; a vendor sells it for the R32; nobody we found has posted a Mk5 R32 install with photos.", "call": "Offered as the upgrade with a fit-check step and honest confidence. If yours fits, it's the smarter long-term answer."}, {"topic": "Catch can", "pos": "Universal cans are sold for the Mk5 R32; a long-time R32 builder notes the Mk5 3.2 already has a cyclone separator.", "call": "Not for a stock car. Boosted or tracked, yes, with a proper baffled can and a winter routine."}], "sources": ["FCP Euro VR6 valve cover gasket and PCV DIY, performed on a 2008 R32 (procedure, torque, part numbers)", "ECS Tuning and DAP Mk5 R32 PCV/valve cover listings", "Audi TT Forum 3.2 BUB PCV diaphragm alternative thread (external valve, P2279)", "UroTuning breather valve 022 103 765 A listing", "RKX 3.2/3.6 diaphragm listing", "R32OC oil catch can thread"], "embeds": [{"id": "1GsuFKV0-Fk", "note": "FCP Euro on a 2008 R32: the service position, manifold and cover removal, and the separator swap. Same car as this guide."}, {"id": "Wl7guwee8u0", "note": "What the vacuum leak sounds like on a Mk5 R32 with a torn diaphragm. Listen before you buy parts."}]}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();

-- 7. Mk5 GTI 2.0T FSI (BPY): turbo kit / upgrade
insert into tasks (id,powertrain_id,guide_id,title,category,group_name,aliases,live,time_label,difficulty) values ('turbo-kit','bpy','turbo-kit','Turbo kit / upgrade','Engine',null,array['turbo','k04','big turbo','gt2871r','gt3071r','boss600','stage 3','turbo upgrade','turbo kit']::text[],true,'8–10 hr',4) on conflict (id) do update set powertrain_id=excluded.powertrain_id, guide_id=excluded.guide_id, title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into guides (id,content) values ('turbo-kit',$j${"id": "turbo-kit", "title": "Turbo kit / upgrade", "fits": "2006–2008 VW GTI · 2.0T FSI (BPY) · manual or DSG", "heroId": "turbo-power-chart", "alsoFits": "Same BPY engine in the 2006–2008 Jetta GLI, 2006–2008 A3 2.0T and 2008 TT 2.0T; software and intercooler fit differ by car", "category": "Engine", "kind": "upgrade", "variants": {"question": "Which kind of turbo?", "hint": "Two very different jobs. A K04 is the factory turbo from the European S3 and Edition 30: it bolts to your manifold, uses your lines, and off-the-shelf software exists for it. A GT-series kit replaces the manifold, adds an external wastegate and braided lines, wants RS4 injectors and a custom tune, and turns a long day into a long weekend.", "options": [{"id": "k04", "label": "K04 kit (APR, CTS, Revo)", "when": "You want 320–350 hp with factory-grade drivability and vendor software. The sensible ceiling for stock internals."}, {"id": "gt", "label": "GT28 / GT30 big-turbo kit (CTS, BOSS600)", "when": "You want 400+ hp, accept lag, a custom tune, bigger fuel system and possibly rods. Only with a complete kit that ships an install sheet."}]}, "chapters": [{"id": "plan", "title": "1 · Plan", "blurb": "Decide the tier, the software, and what has to be on the car before the turbo goes in. Most failed builds fail here."}, {"id": "prep", "title": "2 · Prep", "blurb": "Fluids out, wheel off, everything in the way moved. Same for both tiers."}, {"id": "swap", "title": "3 · Turbo", "blurb": "Old turbo out, new one in. This is where the torque wrench matters."}, {"id": "fuel", "title": "4 · Fuel & spark", "blurb": "The turbo is the easy part. The FSI runs out of fuel pump long before it runs out of turbo."}, {"id": "tune", "title": "5 · Tune & first start", "blurb": "Pre-oil, leak-check, flash, log. Then drive it like you're not sure it's right, because you're not."}], "glance": {"timeFirst": "8–10 hr", "timeRepeat": "6 hr", "difficulty": 4, "cost": "$2,500–4,000 all-in (K04) · $6,000–10,000+ (GT kit)", "risk": "Oil-starved turbo on first start · sheared manifold studs · fuel pump that can't feed it · a tune that doesn't match the hardware", "why": "The BPY's K03 is out of breath at 200 hp. Swapping to the K04 that VW fitted to the S3 and Edition 30 gives 320–350 crank hp with factory drivability and software you can buy off the shelf; a GT-series kit goes past 400 but drags the whole fuel system, clutch and tune with it. Either way this is the most involved bolt-on the car will ever get, and the parts around the turbo decide whether it lasts.", "note": "Mechanical order from a vendor install manual and two owner DIYs; torque values partly from the FSI workshop manual and partly by analogy (flagged). Power figures are vendor crank claims. GT route requires a complete kit with its own sheet; piecemeal builds are out of scope."}, "heroCap": "Crank horsepower by rpm. The K04 fills in the top end the K03 falls off; a GT kit adds another hundred but arrives later. Vendor peaks, typical curve shapes.", "lifespan": {"title": "What to expect", "headline": [{"only": ["k04"], "text": "320–355 crank hp on a full-supporting K04 setup; 240–275 with just the turbo and a tune"}, {"only": ["gt"], "text": "350–470 wheel hp depending on turbo, fuel and octane; owners with GT3076/HTA30 and meth see the top of that"}], "earliest": "The car feels different the first drive; the first failure, if it comes, is fuel or ignition in the first thousand miles", "detail": "A K04 on stock internals is a known quantity: APR, Revo and Unitronic have sold thousands. The FSI's weak links under boost are the high-pressure fuel pump (its piston is undersized), the cam follower it drives, the diverter valve diaphragm, the PCV, and coil packs. Every one of those is in the supporting list because every one of them ends a K04 owner's honeymoon.", "factors": ["Octane (the software has separate 91/93/100 maps)", "Intercooler: the stock one heat-soaks in two pulls", "Fuel pump and injectors matched to the tier", "DSG cars need a TCU flash to hold the torque"], "inspect": ["Cam follower at every oil change for the first year (see that guide); the upgraded HPFP works it harder", "Boost logs after the flash: target vs actual, and fuel rail pressure under load"], "confidence": {"level": "high", "n": 5, "note": "Vendor specs, tuner fueling guidance and owner builds agree on the pattern."}}, "should": {"yesIf": ["You've done intake, downpipe, intercooler and a Stage 2 tune and want the next step", "You're prepared to change the HPFP, injectors and DV at the same time, not later", "Engine is healthy: no oil consumption, no misfires, cam follower recently checked", {"only": ["gt"], "text": "You want 400+ and have a tuner lined up before you buy hardware"}], "codes": [], "notes": ["2006–2008 GTIs are all BPY FSI. If the engine cover says TSI, this is the wrong guide (2008.5–2009 cars).", {"only": ["k04"], "text": "APR's K04 software is sold per ECU box code; not every 2006–2008 box has a file. Read your box code (VCDS/OBDeleven) and confirm with the tuner before ordering hardware. Revo and Unitronic have equivalent K04 stages."}, {"only": ["gt"], "text": "A big-turbo 'kit' for this guide means manifold, turbo, wastegate, downpipe, oil and coolant lines, DV adapter and an install sheet in one box (CTS GT2871R/GT3071R/GT3076R kits, CTS BOSS600). ATP stock-location hardware needs fabrication and is not covered."}, "Not legal for road use in California on a pollution-controlled vehicle; other states vary. Off-road use per the vendors."], "confidence": {"level": "high", "n": 4, "note": "Vendor fitment statements and tuner box-code notes agree."}}, "parts": [{"tier": "aftermarket", "name": "APR K04-64 Turbo System", "pn": "T2100012 (turbo) · T2100011 (with HPFP)", "note": "Genuine BW K04-064, CNC outlet, DV port, gaskets, studs", "price": "$2,000–2,400", "links": [{"store": "APR (product page)", "url": "https://www.goapr.com/products/engine_hardware/turbo/oem/parts/T2100012"}, {"store": "ECS Tuning", "url": "https://www.ecstuning.com/b-apr-parts/k04-turbo-kit/t2100012~kt/"}], "only": ["k04"]}, {"tier": "aftermarket", "name": "CTS Turbo K04 kit (FSI)", "pn": "CTS-TR-1050 (K04) · -1050X (hybrid)", "note": "Genuine K04 with DV relocation hoses; hybrid needs hybrid software", "price": "$1,600–2,200", "links": [{"store": "CTS Turbo", "url": "https://ctsturbo.com/product/cts-turbo-k04-turbocharger-upgrade-for-fsi-and-tsi-gen1-engines-ea113-and-ea888-1/"}, {"store": "UroTuning (K04-X hybrid)", "url": "https://www.urotuning.com/products/cts-turbo-k04-x-hybrid-turbocharger-upgrade-vw-audi-2-0t-fsi-tsi-mk5-gti-gli-a3-8p-cts-tr-1050x"}], "only": ["k04"]}, {"tier": "aftermarket", "name": "K04 software", "pn": "APR K04 · Unitronic Stage 2+ K04 · Revo Stage 3 · GIAC K04", "note": "91/93/100 maps; DSG TCU file for DSG cars", "price": "$500–900", "links": [], "only": ["k04"]}, {"tier": "aftermarket", "name": "CTS Turbo FSI big-turbo kit", "pn": "CTS-MK5-2.0FSI-KIT-2871R / -3071R / -BB", "note": "Manifold, turbo, 39 mm wastegate, 3\" downpipe, lines, DV adapter, inlet with MAF bung", "price": "$3,500–5,000", "links": [{"store": "CTS FSI turbo kit release thread (photos)", "url": "https://www.vwvortex.com/threads/fsi-big-turbo-kits-cts-turbo.5806178/"}], "only": ["gt"]}, {"tier": "aftermarket", "name": "CTS BOSS600 (EA113)", "pn": "BOSS600", "note": "Stock-location, proprietary housing, custom lines; newest option", "price": "$3,000–4,000", "links": [{"store": "Eurosport Tuning", "url": "https://eurosporttuning.com/cts-turbo-ea113-2-0t-boss600-turbo-kit-mk5-gti-jetta-mk6-golf-r-8p-audi-a3-s3/"}], "only": ["gt"]}, {"tier": "aftermarket", "name": "Big-turbo tuning", "pn": "Eurodyne Maestro 7 · Unitronic BT file · pro custom tune", "note": "Must match turbo, injectors and HPFP; DSG TCU file for DSG", "price": "$800–1,500", "links": [], "only": ["gt"]}, {"tier": "oe", "name": "High-pressure fuel pump upgrade", "pn": "APR HPFP · Autotech piston kit", "note": "Required from Stage 2 up; new cam follower with it", "price": "$300–700", "links": []}, {"tier": "oe", "name": "Injectors", "pn": "S3/TTS 06F 906 036 (K04) · RS4/R8 079 906 036 (GT)", "note": "Manifold off to fit; new seals", "price": "$400–900", "links": []}, {"tier": "oe", "name": "Diverter valve, Rev D", "pn": "06H 145 710 D", "note": "Piston type; fits the K04 directly", "price": "$60–90", "links": []}, {"tier": "oe", "name": "Coil packs (×4) and one-step-colder plugs", "pn": "R8 red coils 06E 905 115 E · NGK BKR7EIX (K04) / BKR8EIX (GT)", "note": "Gap 0.028\" for boost", "price": "$120–200", "links": []}, {"tier": "oe", "name": "Turbo gaskets, banjo crush washers, downpipe gasket, manifold nuts", "pn": "in kit; buy spare washers", "note": "Never reuse a crush washer", "price": "$30–60", "links": []}, {"tier": "oe", "name": "Oil, filter, coolant", "pn": "5W-40 VW 502 · G12++/G13", "note": "You're draining both", "price": "$80", "links": []}, {"tier": "oe", "name": "Low-pressure fuel pump upgrade", "pn": "USP / Autotech / DW65v in-tank", "note": "Needed once on RS4 injectors", "price": "$250–500", "links": [], "only": ["gt"]}, {"tier": "oe", "name": "Fuel pressure relief valve, RS4 (140 bar)", "pn": "079 127 043 / 'RS4 PRV'", "note": "Lets the rail run higher on big injectors", "price": "$120–200", "links": [], "only": ["gt"]}, {"tier": "oe", "name": "Clutch and pressure plate", "pn": "Clutchmasters FX400 · SBC Stage 2 · Sachs SRE", "note": "Stock clutch slips at K04 torque on a manual; mandatory on GT", "price": "$900–1,600", "links": []}, {"tier": "oe", "name": "Forged rods (GT30-class builds)", "pn": "IE H-beam or equivalent", "note": "Past ~400 whp the stock rods are the limit", "price": "$700–1,200 + labour", "links": [], "only": ["gt"]}], "aftermarket": [{"name": "Front-mount intercooler", "note": "APR, Forge Twintercooler, CTS, Eurojet. Not optional at K04 power: the stock core heat-soaks after two pulls and the tune pulls timing.", "price": "$500–1,200", "signal": "Required", "links": []}, {"name": "3\" downpipe with high-flow cat, and a 3\" cat-back", "note": "The K04 software assumes a free-flowing downpipe. See the downpipe and cat-back guides.", "price": "$500–1,500", "signal": "Required", "links": []}, {"name": "Intake (Carbonio, CTS, Neuspeed P-Flo)", "note": "MAF-scaled intakes only; the tune is calibrated for them.", "price": "$250–400", "signal": "Required", "links": []}, {"name": "Catch can / PCV fix", "note": "BSH, IE, CTS. The FSI PCV fails under boost and the intake valves carbon up faster; see the PCV and catch can guides.", "price": "$150–350", "signal": "Strongly recommended", "links": []}, {"name": "Boost gauge and a logging cable", "note": "VCDS or OBDeleven for boost, rail pressure and timing logs. You cannot verify the tune without it.", "price": "$80–400", "signal": "Recommended", "links": []}, {"name": "Engine and transmission mounts, pendulum insert", "note": "BSH, VF, 034. Wheel hop and shifter slop get worse with torque.", "price": "$150–500", "signal": "Recommended", "links": []}, {"name": "Water-methanol injection", "note": "Owners at 400+ whp on 93 octane almost all run it. Adds a system to maintain.", "price": "$600–900", "signal": "GT builds on pump gas", "links": [], "only": ["gt"]}], "tools": [{"name": "Lift or tall stands; the turbo comes out the top but you work from below for half of it"}, {"name": "8, 10, 11, 12, 13, 16 mm sockets; 13 and 16 mm wrenches; T25/T27/T30; 5 and 6 mm hex; M8, M10, M12 triple-square"}, {"name": "O2 sensor socket, heat and penetrant for the downpipe, red thread locker for studs, high-temp anti-seize"}, {"name": "Torque wrench 5–60 Nm with an angle gauge (banjo bolts are torque + 45°)"}, {"name": "Drain pans for oil and coolant; VCDS or OBDeleven for the flash and logging"}, {"name": "Fuel-line disconnect tool and a fuel pressure gauge for the LPFP work", "only": ["gt"]}], "before": ["Read the kit's own sheet first. This guide is the order and the traps; the kit sheet has the routing of your specific hoses and lines.", "Cold engine, battery disconnected once the coils are unplugged. The turbo swap is on the hot side; every fastener wants penetrant the night before.", "Confirm your ECU box code and that the tuner has a file for it before a single part is ordered.", {"only": ["gt"], "text": "Book the tuner. A GT kit without a tune scheduled is a car on stands for a month."}, "Do the cam follower inspection now. If it's worn, the new HPFP kills the cam."], "steps": [{"n": 1, "chapter": "plan", "title": "Pick the tier honestly", "blocks": [{"t": "text", "b": "K04: 320–355 crank hp on vendor software with the full supporting list; stock internals, stock rods, factory-style drivability. GT28/GT30: 400+ with lag, a custom tune, RS4 injectors, LPFP, clutch, and rods in the conversation. If the car is a daily and the budget has a ceiling, the K04 is the answer and this chapter is short."}, {"t": "ill", "id": "turbo-power-chart", "cap": "Vendor peak claims on 93 octane. Stock K03 dashed. Real dynos vary with intercooler, fuel and weather."}]}, {"n": 2, "chapter": "plan", "title": "Software first, hardware second", "only": ["k04"], "blocks": [{"t": "text", "b": "APR (K04 program, box-code dependent), Unitronic (Stage 2+ K04), Revo (Stage 3), GIAC (K04). All expect: upgraded HPFP, S3/Ed30 injectors, MAF-scaled intake, downpipe, intercooler. Pick the tuner your local dealer flashes and supports, because you will be back for logs. DSG cars add a TCU file or the box will clamp torque."}, {"t": "note", "b": "CTS's 'tune plus downpipe' minimum runs, and makes about 240–275 hp. The software's headline figures assume the full list."}]}, {"n": 2, "chapter": "plan", "title": "Kit, tuner and fuel as one decision", "only": ["gt"], "blocks": [{"t": "text", "b": "The kit decides the turbo; the turbo decides the injectors and pump; the tuner decides whether it all runs. Eurodyne Maestro (self- or pro-tuned) is the common answer for GT kits; Unitronic and GIAC sell big-turbo files only for named combinations. RS4 injectors plus an upgraded HPFP plus an LPFP upgrade is the fuel system every 400+ whp FSI runs."}, {"t": "warn", "b": "No complete kit, no guide. If the manifold, wastegate, lines and downpipe don't come from one vendor with one sheet, you're fabricating, and nobody can write you steps for that."}]}, {"n": 3, "chapter": "plan", "title": "Supporting mods, in the order they matter", "blocks": [{"t": "text", "b": "Fuel: HPFP upgrade and the right injectors (S3 for K04, RS4 for GT). Air: intercooler, 3\" downpipe, MAF-scaled intake. Ignition: R8/red coils, one-step-colder iridium plugs gapped to 0.028\". Boost control: Rev D diverter valve. Crankcase: PCV fix or catch can. Driveline: clutch on a manual, TCU flash on a DSG, mounts. Do all of it with the turbo, not after the first misfire."}, {"t": "ill", "id": "turbo-plumbing", "cap": "Everything the turbo touches. A K04 reuses all of it; a GT kit replaces the manifold and lines and adds a wastegate."}]}, {"n": 4, "chapter": "prep", "title": "Fluids out, wheel off", "blocks": [{"t": "text", "b": "Car level and high. Drain the oil (you'll be opening the oil feed and return) and drop the coolant at the lower radiator hose (the turbo has coolant feed and return). Right front wheel off, fender liner out (T25s), engine undertray off. Engine cover off, airbox and intake out."}]}, {"n": 5, "chapter": "prep", "title": "Downpipe down", "blocks": [{"t": "text", "b": "O2 sensors out of the downpipe with the socket (mark which is which). Downpipe bracket off the subframe (13 mm), over-axle heat shield off (two 16 mm), then the three downpipe-to-turbo nuts. Heat and penetrant; these are the fasteners that shear. Snake the downpipe out below."}, {"t": "note", "b": "Owners of both tiers say removing the passenger CV axle turns a wrestling match into a job. Optional, but worth it with the manifold coming off."}]}, {"n": 6, "chapter": "prep", "title": "Clear the top", "blocks": [{"t": "text", "b": "Turbo inlet pipe and the heat shield above the turbo (6 mm hex and two M10). Unplug and unclip the coil pack harness, DV and N75 connectors. Turbo outlet 'pancake' pipe off (two T30, two clamps). The metal lines and check valve at the rear of the head: unbolt (two T30) and swing them clear."}]}, {"n": 7, "chapter": "swap", "title": "Lines off the turbo", "caution": true, "blocks": [{"t": "text", "b": "Turbo support bracket off (two M10 below, one 6 mm hex above). Oil feed at the top of the turbo (M12 triple-square) and the adjacent M8; oil feed bracket near the DV from below (M8 triple-square). Coolant return (M12 triple-square) and coolant supply hose at the plastic line by the oil filter (two clamps). Oil return at the block (M8 triple-square). Catch every crush washer and note which line went where."}, {"t": "warn", "b": "Two of the banjo washers are different thicknesses. Photograph each joint before it comes apart; owners have pulled the turbo twice for this."}]}, {"n": 8, "chapter": "swap", "title": "Turbo out", "blocks": [{"t": "text", "b": "Five 13 mm nuts hold the manifold to the head. Wiggle the manifold and turbo free as one piece and lift it out the top, turbine side up; the compressor outlet catches on the block, so angle it. Studs that come out with the nuts go back in by hand with two nuts jammed; there is no factory torque for them."}, {"t": "note", "only": ["k04"], "b": "With the assembly on the bench, unbolt the K03 from the manifold, clean the flange, and bolt the K04 on with the kit gasket. Transfer the coolant and oil lines to the K04 exactly as they sat on the K03, new crush washers on every banjo."}, {"t": "note", "only": ["gt"], "b": "The stock manifold retires. Build the kit manifold, turbo and wastegate on the bench per the kit sheet; check the wastegate spring against the tune's target boost before it goes in."}]}, {"n": 9, "chapter": "swap", "title": "Dress the new turbo", "only": ["k04"], "blocks": [{"t": "text", "b": "Coolant plug into the K04's unused lower port (6 mm hex). Diverter valve onto the K04's port with the kit's three 5 mm hex bolts and lock washers; fit a Rev D, not the old one. N75 and its vacuum hose across. Downpipe studs into the turbine flange, small end in, red thread locker. Kit silicone outlet on the compressor at the same angle the old outlet sat."}, {"t": "torque", "label": "Coolant blanking plug (6 mm hex)", "nm": 54, "c": {"level": "medium", "n": 2, "note": "40 lb-ft in the CTS manual; 38–40 lb-ft in the owner DIY."}}, {"t": "torque", "label": "Turbo to manifold (K04 on stock manifold)", "nm": 30, "c": {"level": "single", "n": 1, "note": "No FSI figure found; 22 ft-lb is the 1.8T value for the same joint style. Even, in a cross, with anti-seize on the studs."}}]}, {"n": 10, "chapter": "swap", "title": "In, and nuts in sequence", "caution": true, "blocks": [{"t": "text", "b": "New manifold gasket on the head, tab orientation as the old one. Lower the assembly in, turbine up, and seat the manifold in the locating blocks on the head. Number the five studs 1–5 from the passenger side and tighten 1-3-5-4-2, in passes: snug, then 10, then final. The manifold warps if you race it."}, {"t": "torque", "label": "Exhaust manifold nuts to head (5× 13 mm)", "nm": 20, "c": {"level": "medium", "n": 2, "note": "20 Nm per the FSI workshop manual (owner citation); the TSI is 25. Sequence 1-3-5-4-2 in staged passes from two DIYs."}}]}, {"n": 11, "chapter": "swap", "title": "Lines back, torqued", "caution": true, "blocks": [{"t": "text", "b": "Oil return with its new gasket. Coolant feed and return banjos with new crush washers both sides; thick washer on the firewall-side line only. Oil feed at the top. Support bracket back. Downpipe up with the kit gasket, then bracket and heat shield. O2 sensors in with anti-seize on the threads only."}, {"t": "torque", "label": "Banjo bolts, oil and coolant (M12 triple-square)", "nm": 25, "alt": [], "c": {"level": "medium", "n": 2, "note": "18 lb-ft + 45° in the CTS manual; 20 Nm + 45° in the owner DIY. Angle matters more than the number."}, "note": "then +45°"}, {"t": "torque", "label": "Downpipe to turbo (3 nuts)", "nm": 40, "c": {"level": "single", "n": 1, "note": "30 ft-lb is the 1.8T figure for the same joint; no FSI figure found. Recheck after the first heat cycle."}}, {"t": "note", "only": ["gt"], "b": "GT kits: braided oil feed and drain with AN fittings, coolant block-off or relocation per the sheet, wastegate dump into the downpipe. Torque the AN fittings to the kit sheet, not to these plates."}]}, {"n": 12, "chapter": "fuel", "title": "High-pressure pump and cam follower", "caution": true, "blocks": [{"t": "text", "b": "With the top clear, this is the moment. The HPFP sits on the head at the back, driven by the intake cam through a follower. Depressurise the rail (fuel pump fuse out, crank), remove the pump (three T30), inspect the follower and the cam lobe, fit the upgraded pump or piston kit with a new follower and O-ring."}, {"t": "torque", "label": "HPFP bolts (3× T30)", "nm": 10, "c": {"level": "high", "n": 3, "note": "Same figure as the cam follower guide: factory value, corroborated."}}, {"t": "warn", "b": "A worn follower with an upgraded pump takes the cam lobe with it in a few thousand miles. If the coating is through, stop and read the cam follower guide."}]}, {"n": 13, "chapter": "fuel", "title": "Injectors", "blocks": [{"t": "text", "b": "S3/TTS injectors for the K04, RS4/R8 for a GT kit. They sit under the intake manifold: manifold off (see the PCV or intake manifold guides for the FSI order), rail off, injectors out with the puller, new seals and Teflon rings sized with the tool, reinstall. New rail bolts."}, {"t": "note", "only": ["gt"], "b": "RS4 injectors idle rough and smoke cold until the tune is dialled. Expected. Some owners run one-step-hotter plugs in winter for cold starts."}]}, {"n": 14, "chapter": "fuel", "title": "Low-pressure pump and relief valve", "only": ["gt"], "blocks": [{"t": "text", "b": "The in-tank pump can't keep the rail fed at RS4 flow. Rear seat up, access plate off, upgraded LPFP (USP, Autotech, DW65v) into the basket per its sheet. Fit the RS4 fuel pressure relief valve on the rail so the HPFP can hold 130–140 bar. Both are required by every tuner who'll touch a GT FSI."}]}, {"n": 15, "chapter": "fuel", "title": "Spark, boost control, crankcase", "blocks": [{"t": "text", "b": "Four R8 coils, one-step-colder iridium plugs gapped to 0.028\", 25–30 Nm. Rev D diverter valve confirmed on the turbo. PCV: new valve or plate and catch can; the FSI's PCV fails first under boost. Intake, intercooler and downpipe complete so the tune sees the airflow it expects."}]}, {"n": 16, "chapter": "fuel", "title": "Clutch or DSG", "blocks": [{"t": "text", "b": "Manual: the stock clutch holds a K04 for a while and a GT kit for a week. Plan the clutch (see the clutch guide) before the tune goes on, or drive Stage 1 until it's done. DSG: the TCU file is not optional; without it the box clamps torque and clutch-pack temperatures climb. Fresh DSG service first."}]}, {"n": 17, "chapter": "tune", "title": "Fill and pre-oil", "caution": true, "blocks": [{"t": "text", "b": "Oil and filter, coolant filled and bled with the heater on. Coils still unplugged: crank for 10–15 seconds, wait, repeat once, so the turbo's bearings see oil before the first fire. Then plug the coils in."}, {"t": "warn", "b": "A dry first start is how new turbos die in the driveway. Do the crank."}]}, {"n": 18, "chapter": "tune", "title": "First start, leak check", "blocks": [{"t": "text", "b": "Undertray still off. Start, idle five minutes, look at every banjo and clamp with a light: oil, coolant, exhaust smell at the manifold. Some smoke off the new turbo is normal. Shut down, recheck oil level, recheck the downpipe nuts after it cools."}]}, {"n": 19, "chapter": "tune", "title": "Flash and log", "blocks": [{"t": "text", "b": "Stock ECU with a K04 will overboost and limp. Flash the kit software (and the TCU file on a DSG) before any spirited drive. First drive: gentle, logging boost request vs actual, rail pressure, timing pull, and misfire counters. Anything that doesn't match the tuner's expected values goes back to the tuner as a log, not a guess."}, {"t": "note", "only": ["gt"], "b": "Maestro: start with the base file for your turbo and injectors, log, adjust in small steps or hand the logs to a pro. Do not chase peak boost before rail pressure holds at redline."}]}, {"n": 20, "chapter": "tune", "title": "Break in and recheck", "blocks": [{"t": "text", "b": "Five hundred easy miles, then an oil change. Retorque the manifold nuts and downpipe once hot-cold. Cam follower inspection at that oil change and every one after for the first year. Then enjoy the car the K03 never let it be."}]}], "alsoReplace": [{"name": "Cam follower and intake cam inspection", "why": "The upgraded HPFP loads the follower harder. Inspect now and every oil change for a year."}, {"name": "Intake manifold flap and runner motor", "why": "Manifold is off for the injectors; the P2015 flap fix is a cheap add."}, {"name": "Timing belt and water pump", "why": "If it's near 80k, do it while the front of the engine is accessible and you're draining coolant anyway."}, {"name": "Thermostat and coolant temp sensor", "why": "Coolant is out. Both are common FSI weak spots."}, {"name": "Engine and transmission mounts", "why": "Torque went up 60 %. Inserts or full mounts stop the wheel hop."}], "check": {"tab": "Which tier?", "title": "Which tier fits the car and the budget?", "illId": "turbo-power-chart", "illCap": "The gap between the curves is also the gap between the parts lists.", "rows": [{"see": "Daily driver, stock engine, want the next step after Stage 2", "means": "K04 on stock internals with the full supporting list.", "do": "K04 route. Budget the intercooler and HPFP as part of the price."}, {"see": "Manual with an original clutch", "means": "It will slip at K04 torque.", "do": "Clutch first or at the same time."}, {"see": "DSG", "means": "TCU clamps torque without a flash.", "do": "TCU file with the ECU file; fresh DSG service."}, {"see": "Chasing 400+ whp on 93", "means": "GT kit, RS4 injectors, LPFP, custom tune, probably meth.", "do": "GT route with a tuner booked and a complete kit."}, {"see": "Chasing 450+ whp", "means": "Stock rods are the limit.", "do": "Rods and pistons before the tune, or a lower boost target."}, {"see": "Unknown ECU box code, or a tune the vendor can't confirm", "means": "Software may not exist for your car.", "do": "Read the box code and email the tuner before buying anything."}], "c": {"level": "community", "n": 5, "note": "Tier thresholds from tuner fueling guidance and the spread of owner builds."}}, "aftercare": ["Oil change at 500 miles, then normal 5k intervals with 502-spec 5W-40; boosted FSIs are hard on oil.", "Retorque manifold nuts and downpipe after the first full heat cycle.", "Log once a month for the first six months: rail pressure at redline, boost vs request, misfires.", "Cam follower every oil change for a year, then every other.", "Keep the stock turbo, manifold and ECU file. Buyers of a modified GTI ask."], "disagreements": [{"topic": "K04 minimum supporting mods", "pos": "CTS: tune and downpipe is enough to run. APR: HPFP, injectors, intake, exhaust, intercooler required for the advertised power.", "call": "APR's list. The 'runs' setup makes 240–275 hp and heat-soaks; the point of a K04 is 320+."}, {"topic": "Genuine K04 or billet hybrid", "pos": "Hybrids (CTS K04-X and others) make more up top; software must be hybrid-specific and vendors warn against CHRA-in-stock-housing builds.", "call": "Genuine K04 with off-the-shelf software unless a tuner has a hybrid file for your exact unit."}, {"topic": "Off-the-shelf big-turbo files vs custom", "pos": "Unitronic and GIAC sell files for named turbo/injector combos; Eurodyne Maestro and pro tuners do custom.", "call": "Custom or Maestro for any GT build; OTS only when the tuner names your exact hardware."}, {"topic": "When rods", "pos": "Owners with 400 whp on stock rods exist; builds past 450 mostly have IE or forged rods.", "call": "Stock rods for K04 and GT28-class; plan rods for GT30/BOSS past ~400 whp."}, {"topic": "Piecemeal big-turbo builds", "pos": "ATP hardware plus your own lines and charge pipes is cheaper.", "call": "Real, common, and unguideable. Not in scope."}], "sources": ["APR K04-64 Turbo System pages and dealer listings (kit contents, software modes, power figures, requirements)", "CTS Turbo K04, K04-X, FSI GT-series and BOSS600 kit listings and forum release threads", "CTS Turbo Mk6 2.0 TSI K04 installation manual (mechanical order, banjo and plug torque)", "golfmkv / golfmk6 / VW Vortex APR K04 install DIY (Mk5) and manifold-stud thread (FSI 20 Nm)", "Motoza Performance FSI injector and fueling guide", "VW Vortex and golfmkv big-turbo FSI build threads and FAQ (fuel system, tuning, plugs, rods)", "ATP Turbo GT2871R / GT3071R kit listings (fabrication statement)"], "embeds": [{"id": "zUkKhAOMxCU", "note": "Mk5 GTI FSI K04 conversion and dyno setup (2017). The clearest look at the kit itself: how the K04 drops in place of the K03 with the diverter valve where the stock one sat.", "only": ["k04"]}, {"id": "KmBSXfrrRWU", "note": "An owner's Mk5 GTI K04 swap, start to finish (2022). Not a step-by-step; useful for seeing the access and the order of things coming apart.", "only": ["k04"]}, {"id": "ulRf31GppsM", "note": "Pulling the turbo out of a Mk5 GTI, part 2 of a K04 series (2022). Matches chapter 3 here.", "only": ["k04"]}]}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();


-- 020: intercooler upgrade guide, diverter valve options, headlights to Exterior, turbo kit links and videos
-- Run in the Supabase SQL editor after 019. Safe to re-run.

-- 1. Intercooler upgrade (shared FSI/TSI)
insert into tasks (id,powertrain_id,guide_id,title,category,group_name,aliases,live,time_label,difficulty) values ('intercooler','bpy','intercooler','Intercooler upgrade','Engine',null,array['intercooler','fmic','front mount','charge pipe','throttle body pipe','heat soak','ic']::text[],true,'3–5 hr',3) on conflict (id) do update set powertrain_id=excluded.powertrain_id, guide_id=excluded.guide_id, title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into tasks (id,powertrain_id,guide_id,title,category,group_name,aliases,live,time_label,difficulty) values ('intercooler-tsi','ccta','intercooler','Intercooler upgrade','Engine',null,array['intercooler','fmic','front mount','charge pipe','throttle body pipe','heat soak','ic']::text[],true,'3–5 hr',3) on conflict (id) do update set powertrain_id=excluded.powertrain_id, guide_id=excluded.guide_id, title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into guides (id,content) values ('intercooler',$j${"id": "intercooler", "title": "Intercooler upgrade", "fits": "2006–2009 VW GTI · 2.0T FSI & TSI", "heroId": "intercooler-temps", "alsoFits": "Mk5 Jetta GLI, Mk6 GTI, Eos, A3 8P 2.0T share the sandwich intercooler and most kits; charge pipes differ FSI vs TSI", "category": "Engine", "kind": "upgrade", "variants": {"questions": [{"question": "Which style of intercooler?", "hint": "The factory core is sandwiched between the A/C condenser and the radiator, low behind the bumper. You can replace it with a bigger core in that same spot (APR, IE, CTS, Neuspeed: direct fit, bumper and radiator support come off), or hang a large front-mount core off the crash beam behind the bumper cover (ECS, Eurojet, Godspeed) fed by new hoses, leaving the factory core in place or removed.", "options": [{"id": "stock", "label": "OE-location upgrade (bigger core, same spot)", "when": "Cleanest look, keeps factory airflow to the radiator, uses the factory hose routing. More disassembly on the day."}, {"id": "fmic", "label": "Front-mount kit (core behind the bumper)", "when": "Coolest outlet temps, easiest access later, visible through the grille. New hose runs; some kits drop core volume behind the radiator."}]}, {"question": "Replacing the charge pipes too?", "hint": "Between the turbo and the throttle body there are three pieces you can swap while the front is apart: the turbo outlet pipe (the plastic 'pancake' on the FSI), the intercooler hoses, and the throttle body pipe with the MAP sensor on it. Kits come both ways: 'for OEM charge pipes' or 'with charge pipes'.", "options": [{"id": "nopipes", "label": "Intercooler only", "when": "Keep the factory turbo outlet, hoses (where the kit reuses them) and throttle body pipe."}, {"id": "pipes", "label": "Intercooler plus charge pipes", "when": "Metal turbo outlet pipe, silicone hoses, aluminium throttle body pipe. Adds an hour and the noise-pipe plug."}]}]}, "chapters": [{"id": "plan", "title": "1 · Plan", "blurb": "Which core, which kit, and what it's worth on your car."}, {"id": "access", "title": "2 · Access", "blurb": "Bumper off. The OE-location route also puts the radiator support in service position."}, {"id": "cooler", "title": "3 · Cooler", "blurb": "Old core out and new one in, or the front-mount hung on the crash beam."}, {"id": "pipes", "title": "4 · Charge pipes", "blurb": "Turbo outlet, hoses, throttle body pipe and the MAP sensor."}, {"id": "finish", "title": "5 · Finish", "blurb": "Bumper back, coolant (OE route), leak check, and a heat-soak test you can actually feel."}], "glance": {"timeFirst": "3–5 hr (OE-location) · 2–3 hr (front-mount)", "timeRepeat": "2 hr", "difficulty": 3, "cost": "$450–1,100 core · +$250–450 charge pipes", "risk": "Coolant everywhere on the OE route · a boost leak at a coupler you can't see · condenser lines bent while tilting it", "why": "The factory intercooler is a thin core wedged between two heat exchangers. On a tuned car it soaks after two hard pulls and the ECU starts pulling timing to protect the engine; APR measured the stock car doing exactly that on the third dyno run. A bigger core, or a core out in fresh air, keeps intake temps flat pull after pull. It doesn't add peak power so much as stop the car losing it.", "note": "Procedure from an OE-location kit's install sheet (IE) and front-mount kit documentation (ECS); temperature and power figures are vendor dyno claims, plotted as shapes."}, "heroCap": "Outlet air temperature across five back-to-back pulls. The stock core climbs until the tune protects itself; upgraded cores stay flat. Shapes anchored to APR and ECS test claims.", "lifespan": {"title": "What to expect", "headline": ["Flat intake temps pull after pull; 5–15 whp back on a tuned car that was heat-soaking, more on a K04"], "earliest": "The first hot day after a tune is when owners notice the stock core", "detail": "On a stock car the gain is small and the point is headroom. On a Stage 2 or K04 car the gain is whatever the tune was pulling in timing on hot days, which owners describe as the car 'not falling on its face' on the third pull. ECS measured +9 whp and +10 wtq with a 66 °F lower outlet on a K04 Mk6; APR measured the stock core letting temps run about 40 °F higher by the fifth pull.", "factors": ["Ambient temperature and how you drive it (heat soak is a repeated-pull problem)", "Boost level: K04 cars need this, Stage 1 cars want it", "Core volume vs pressure drop: a huge dense core costs boost response"], "inspect": ["Log intake air temperature (IAT) on repeated pulls before and after; the number on the third pull is the one that matters", "Look at every coupler after the first week: a slow boost leak shows as an oily ring at the clamp"], "confidence": {"level": "community", "n": 4, "note": "Vendor dyno claims from two suppliers plus owner reports; no independent comparison test across kits."}}, "should": {"yesIf": ["Tuned (Stage 1+) and the car feels weaker on the third hard pull than the first", "Planning a K04 or bigger; every vendor lists an intercooler as required", "Logging shows intake temps climbing 30 °F or more over back-to-back pulls", "Original intercooler with bent fins or a weeping end tank"], "codes": [], "notes": ["Both FSI and TSI Mk5 cars use the same sandwich intercooler and take the same cores; the charge pipes differ (the FSI's turbo outlet is the plastic 'pancake', the TSI's is a different pipe), so buy pipe kits by engine.", {"only": ["stock"], "text": "OE-location cores: APR (2.25 × 16.25 × 22 in, 40 % larger than stock, comes with hoses and a billet adapter), IE FDS (direct fit, install guide is public and is the one this procedure follows), CTS and Neuspeed direct-fit cores. All keep factory airflow through the radiator behind them."}, {"only": ["fmic"], "text": "Front-mount kits: ECS (23⅝ × 6½ × 3 in bar-and-plate, bolt-on brackets, sold 'for OEM charge pipes' or 'with ECS charge pipes'), Eurojet, Godspeed. Forge's Twintercooler is a hybrid: a second core in front of the crash bar plumbed in series with the factory core, keeping both."}, {"only": ["pipes"], "text": "Charge pipes: ECS, CTS and IE make FSI turbo outlet pipes and throttle body pipes; APR and IE sell hose sets. The throttle body pipe usually drops the factory noise pipe: buy the firewall plug (ECS ES#263635) with it."}, "Not legal for road use in California on a pollution-controlled vehicle; other states vary."], "confidence": {"level": "high", "n": 4, "note": "Kit contents, dimensions and fitment from vendor listings and install sheets agree."}}, "parts": [{"tier": "aftermarket", "name": "OE-location intercooler kit", "pn": "APR IC100016 · IE IETPCB1 · CTS CTS-IC-MK5 · Neuspeed", "note": "Core, silicone hoses, clamps, hardware; IE includes condenser spacers", "price": "$550–1,000", "links": [{"store": "IE (install guide)", "url": "https://cdn.performancebyie.com/guides/IETPCB1%20-%20MK5_MK6_IC_INSTALL_GUIDE.pdf"}, {"store": "APR product page", "url": "https://www.goapr.com/products/engine_hardware/charge_air_coolers/air_to_air_coolers/apr_intercooler_system_-_pq35_18t_and_20t/"}], "only": ["stock"]}, {"tier": "aftermarket", "name": "Front-mount intercooler kit", "pn": "ECS 007812LA01-01KT (for OEM pipes) · Eurojet · Godspeed", "note": "Core, cast end tanks, brackets, 4-ply couplers, T-bolt clamps", "price": "$450–900", "links": [{"store": "ECS Tuning", "url": "https://www.ecstuning.com/b-ecs-parts/mk5-gti-jetta-front-mount-intercooler-kit-for-oem-charge-pipes/007812la01-01kt/"}], "only": ["fmic+nopipes"]}, {"tier": "aftermarket", "name": "Front-mount intercooler kit with charge pipes", "pn": "ECS 007812LA01-02KT/-03KT · Eurojet with pipes", "note": "Adds turbo outlet pipe, throttle body pipe with MAP flange, all couplers", "price": "$750–1,100", "links": [{"store": "ECS Tuning (TSI kit page; FSI variant listed alongside)", "url": "https://www.ecstuning.com/b-ecs-parts/mk5-gti-jetta-tsi-front-mount-intercooler-kit-with-ecs-charge-pipes/007812la01-03kt/"}], "only": ["fmic+pipes"]}, {"tier": "aftermarket", "name": "Turbo outlet pipe (FSI 'pancake' replacement)", "pn": "CTS TOP · ECS · IE", "note": "Metal, with the DV port where your valve sits", "price": "$120–200", "links": [], "only": ["stock+pipes"]}, {"tier": "aftermarket", "name": "Throttle body pipe", "pn": "CTS · ECS · Neuspeed", "note": "Aluminium, MAP sensor flange, noise-pipe delete", "price": "$120–180", "links": [], "only": ["stock+pipes"]}, {"tier": "oe", "name": "Noise pipe firewall plug", "pn": "ES#263635 (ECS) or equivalent", "note": "Covers the hole the noise pipe leaves", "price": "$10", "links": [], "only": ["pipes"]}, {"tier": "oe", "name": "Intercooler hose o-ring (turbo outlet joint)", "pn": "reuse from the factory hose or buy new", "note": "IE's adapter takes the factory o-ring", "price": "$4", "links": [], "only": ["stock"]}, {"tier": "oe", "name": "Coolant, G12++/G13, one gallon premixed", "pn": "G 012 A8G / G 013 A8J", "note": "Radiator comes out on the OE route", "price": "$20", "links": [], "only": ["stock"]}, {"tier": "oe", "name": "Two long M10 bolts for service position", "pn": "M10 × 75 mm (IE includes them)", "note": "Holds the radiator support while it's slid forward", "price": "$4", "links": [], "only": ["stock"]}, {"tier": "oe", "name": "T-bolt clamps, spare", "pn": "60–80 mm ×2", "note": "Kits include them; one always gets dropped", "price": "$12", "links": []}], "aftermarket": [{"name": "APR Intercooler System (OE location)", "note": "Bar-and-plate, louvered fins, cast tanks, billet adapter. APR's own five-pull test: about 40 °F cooler than stock by run five, with the stock car pulling boost from run three.", "price": "$850–1,000", "signal": "Reference", "links": []}, {"name": "IE FDS intercooler (OE location)", "note": "Flow-distribution end tanks, public install guide, condenser spacers in the box. Best-documented install of the group.", "price": "$600–750", "signal": "Documented", "links": []}, {"name": "ECS front-mount kit", "note": "Bolt-on brackets, no drilling. ECS's dyno on a K04 Mk6: +9 whp, +10 wtq, 66 °F lower outlet, at a slight pressure drop from a smaller total core.", "price": "$450–1,100", "signal": "Front-mount", "links": []}, {"name": "Forge Twintercooler", "note": "Second core ahead of the crash bar in series with the factory one. Keeps the OEM core, so it's reversible; owners report it clearly beats stock on heat soak.", "price": "$800–1,000", "signal": "Hybrid", "links": []}, {"name": "Charge pipe sets (CTS, ECS, IE)", "note": "The FSI plastic turbo outlet pipe cracks with age and its DV port is a leak point; metal pipes are as much a repair as an upgrade at this age.", "price": "$250–450", "signal": "Do with the cooler", "links": []}], "tools": [{"name": "T25 and T30 Torx; 16 mm socket on a 3/8\" ratchet with a 6\" extension; long 5 mm hex; flat screwdriver for spring clamps"}, {"name": "Drain pan and funnel for coolant; a second pair of hands for the radiator", "only": ["stock"]}, {"name": "Hose-clamp pliers; T-bolt clamp driver (usually 8 mm or 10 mm)"}, {"name": "Step bit or hole saw only if your throttle body pipe needs the MAP sensor hole enlarged (kit sheet will say)", "only": ["pipes"]}], "before": ["Cold engine. The OE route drains the radiator; the front-mount route doesn't, but the couplers are stiff cold and easy hot, so warm the silicone in the sun.", {"only": ["stock"], "text": "Read the kit sheet for spacer and bolt lengths: IE ships different condenser and radiator bolts depending on whether your car has the ozone sensor on the radiator."}, {"only": ["fmic"], "text": "Check the kit's brackets against your crash beam before the bumper is off for the night; early and late Mk5 beams differ and ECS lists which."}, "Photograph the fog light and side marker plugs and the washer hose before the bumper comes off."], "steps": [{"n": 1, "chapter": "plan", "title": "Pick the style with your eyes open", "blocks": [{"t": "text", "b": "OE-location: cleaner, keeps radiator airflow, but the radiator comes out and coolant with it. Front-mount: cooler outlet, easier to service later, visible; some kits have less total core than stock and a touch more pressure drop, which ECS states plainly on its own page. Both beat the factory sandwich by a wide margin on heat soak."}, {"t": "ill", "id": "intercooler-temps", "cap": "The gap after run three is the whole argument."}]}, {"n": 2, "chapter": "plan", "title": "Decide on pipes now, not after", "blocks": [{"t": "text", "b": "The front is apart once. If the FSI's plastic turbo outlet pipe is original, it's fifteen years old and its DV port is a known leak; the throttle body pipe carries the MAP sensor and the noise pipe. Kits are sold with or without them; buy the version you'll actually fit."}, {"t": "note", "only": ["pipes"], "b": "Throttle body pipes drop the factory noise pipe. Order the firewall plug with the pipe or you'll drive around with a hole into the cabin."}]}, {"n": 3, "chapter": "access", "title": "Grille and bumper cover off", "blocks": [{"t": "text", "b": "T25s along the top of the grille, pull it from the bottom to free the lock tabs. Bumper cover: two T25 on top, five in each wheel well, ten along the bottom; undertray off (eight bolts). Pull the 'wings' at the fenders outward and lift the cover away, unplugging fog lights and side markers; headlight-washer cars unclip the hose at the pump and cap the tank. Slide the foam off the crash beam."}, {"t": "ill", "id": "bumper-fasteners", "cap": "Every T25 on the cover, front and underneath. Undertray bolts in grey."}]}, {"n": 4, "chapter": "access", "title": "Radiator support to service position", "only": ["stock"], "blocks": [{"t": "text", "b": "Factory airbox cars: two T25s on the air guide at the radiator support. Four 16 mm bolts each side hold the radiator support to the frame rails. Thread the two long M10 bolts into the outer lower holes first, then remove the rest and slide the support forward on the long bolts. It stays attached to the car; you get about four inches."}, {"t": "ill", "id": "ic-service-position", "cap": "Two long bolts in first, four 16 mm out each side, slide it forward. It stays on the car."}]}, {"n": 5, "chapter": "access", "title": "Hoses off and coolant out", "only": ["stock"], "blocks": [{"t": "text", "b": "Unclip both intercooler hoses at the core. Left hose off the throttle body pipe (screw clamp); right hose off the turbo outlet pipe (spring clip, flat screwdriver). Cap off, pan under, lower radiator hose unclipped to drain, upper hose unclipped. Fan shroud: four T30, unplug fans, out from below."}]}, {"n": 6, "chapter": "cooler", "title": "Radiator and old core out", "only": ["stock"], "caution": true, "blocks": [{"t": "text", "b": "Four T30 hold the radiator to the intercooler; radiator out from below and drained. Two T30 on top hold the intercooler to the support; remove them and tilt the intercooler and A/C condenser back a few inches together. Now the condenser-to-intercooler screws: four on the front face, one by the A/C lines on the right. Lift the old core off its locating pins and out the bottom; keep the plastic mount brackets."}, {"t": "warn", "b": "The condenser stays connected. Tilt it, never lever it; a kinked A/C line is a recharge and a new condenser."}, {"t": "ill", "id": "ic-sandwich", "cap": "The stack from the front: condenser, core, radiator, shroud, and how many bolts hold each to the next."}]}, {"n": 7, "chapter": "cooler", "title": "New core in", "only": ["stock"], "blocks": [{"t": "text", "b": "Plugs and cardboard off the new core; factory brackets slid on. In from the bottom, inlet and outlet facing rearward. Condenser bolted to it with the kit's M6×18 bolts, washers under the heads, the spacers between condenser and core. Locating pins into the support grommets, the two top bolts back in."}, {"t": "torque", "label": "Condenser-to-intercooler and radiator-to-intercooler bolts (M6)", "nm": 8, "c": {"level": "single", "n": 1, "note": "No figure in the kit sheet; M6 into cast aluminium tanks, snug. Over-tightening cracks a tank ear."}}]}, {"n": 8, "chapter": "cooler", "title": "Radiator back, fans, hoses", "only": ["stock"], "blocks": [{"t": "text", "b": "Radiator onto the new core with the kit's M6×14 bolts (M6×16 with the thin spacers on ozone-sensor cars). Fan shroud with the factory T30s. Fans plugged, coolant hoses clipped. If the radiator won't drop onto its lower mount, ease the A/C lines outward a little; they sit on it."}]}, {"n": 9, "chapter": "cooler", "title": "Couplers on", "only": ["stock"], "blocks": [{"t": "text", "b": "Take the o-ring off the factory right-hand hose and fit it to the kit's billet adapter; adapter into the turbo outlet pipe and clip it. Kit silicone: the L-shaped hose on the left to the throttle body pipe, the S-shaped on the right to the adapter. Clamps slid on first, then tightened."}, {"t": "note", "only": ["pipes"], "b": "Fitting new charge pipes too? Leave the couplers loose here and go to the pipes chapter before the final tighten."}, {"t": "ill", "id": "ic-oe-hoses", "cap": "L hose on the driver side to the throttle body pipe; S hose on the passenger side to the adapter."}]}, {"n": 6, "chapter": "cooler", "title": "Hang the core on the crash beam", "only": ["fmic"], "blocks": [{"t": "text", "b": "Brackets bolt to the existing crash-beam holes; ECS's need no drilling. Bolt the brackets to the core loosely, offer it up, and centre it in the bumper opening with the inlet on the passenger side (turbo side) and outlet on the driver's side. Tighten the beam bolts, then the bracket-to-core bolts."}, {"t": "warn", "b": "Check the core doesn't touch the beam or the bumper cover foam anywhere; a vibrating contact point wears through an end tank."}, {"t": "ill", "id": "ic-fmic-mount", "cap": "Brackets to the beam, core to the brackets, factory core left behind it."}]}, {"n": 7, "chapter": "cooler", "title": "Bypass the factory core", "only": ["fmic"], "blocks": [{"t": "text", "b": "Unclip the factory hose from the turbo outlet pipe (spring clip) and from the throttle body pipe (screw clamp). The factory sandwich core can stay where it is, sealed off, which is what the kits are designed around; removing it means the OE-location procedure's radiator-out work for no gain."}, {"t": "note", "b": "Some owners remove the stock core for airflow to the radiator. Fine, but it's the whole radiator-out job; do it only if the radiator is coming out anyway."}]}, {"n": 8, "chapter": "cooler", "title": "Route the new hoses", "only": ["fmic"], "blocks": [{"t": "text", "b": "Inlet run: turbo outlet pipe down and forward to the core's passenger-side tank. Outlet run: driver's tank up to the throttle body pipe. Couplers and clamps loose until every bend sits without twisting; then work along tightening. Nothing rubs the crash beam, the headlight or the bumper bracket."}, {"t": "note", "only": ["pipes"], "b": "Fitting charge pipes too? Leave the couplers loose and go to the pipes chapter first."}]}, {"n": 10, "chapter": "pipes", "title": "Turbo outlet pipe", "only": ["pipes"], "blocks": [{"t": "text", "b": "FSI: the plastic pancake pipe bolts to the turbo's compressor outlet with two T30 and carries the diverter valve on its port. Unbolt the DV (three T30) and move it to the new pipe with a new o-ring, fit the new pipe with its gasket or o-ring, and tighten the two T30. TSI: the kit pipe replaces the outlet elbow; same DV move."}, {"t": "torque", "label": "Turbo outlet pipe to compressor (2× T30)", "nm": 8, "c": {"level": "single", "n": 1, "note": "Small fasteners into the compressor cover; kit sheets say snug."}}, {"t": "ill", "id": "ic-charge-pipes", "cap": "The whole path, with the two pipes a kit replaces outlined in red."}]}, {"n": 11, "chapter": "pipes", "title": "Throttle body pipe and MAP sensor", "only": ["pipes"], "caution": true, "blocks": [{"t": "text", "b": "Unplug the MAP sensor and the noise pipe from the factory throttle body pipe, loosen the clamp at the throttle body and the hose clamp, and lift the pipe out. Move the MAP sensor to the new pipe's flange with its o-ring (two T25 or the kit's screws). Plug the noise-pipe hole in the firewall. New pipe onto the throttle body, clamp snug."}, {"t": "warn", "b": "The MAP sensor must seal or the car runs rich and throws codes. New o-ring, seated flat, screws snug. Cross-thread the aluminium flange and you're buying a pipe."}]}, {"n": 12, "chapter": "pipes", "title": "Couplers final", "only": ["pipes"], "blocks": [{"t": "text", "b": "Back to the couplers you left loose: every joint pushed fully home, clamps square on the hose, tightened firmly. T-bolt clamps want about 5 Nm; spring clips just seat. Wiggle every pipe; nothing should rotate."}]}, {"n": 13, "chapter": "finish", "title": "Support, bumper, grille", "blocks": [{"t": "text", "b": "OE route: radiator support bolts in (three in, then pull the long M10s, then the last two). Fog lights and side markers plugged, washer hose on, bumper cover on and its T25s, grille clicked in. Undertray: on the OE route one bolt fouls the new silicone; IE says pull that threaded insert and leave the bolt out."}]}, {"n": 14, "chapter": "finish", "title": "Coolant and first start", "only": ["stock"], "blocks": [{"t": "text", "b": "Fill with premixed G12++/G13, heater on hot, cap off, idle until the thermostat opens and the level settles, top up, cap on. Check both radiator hoses and the drain point for drips."}]}, {"n": 15, "chapter": "finish", "title": "Leak check and the heat-soak test", "blocks": [{"t": "text", "b": "Start, idle, listen at each coupler for a hiss under a light throttle blip. Then the test you did before you started: three back-to-back pulls in third with IAT logged. The number on pull three is the one that should have moved."}, {"t": "note", "b": "A slow boost leak shows in a week as an oily ring at a clamp and a soft top end. Recheck every clamp after the first drive and again after the first hot week."}]}], "alsoReplace": [{"name": "Diverter valve", "why": "It's in your hand when the turbo outlet pipe comes off. Piston valve or DV+; see that guide.", "only": ["pipes"]}, {"name": "Intercooler hoses (if the kit reuses them)", "why": "Factory hoses are the same age as the core and balloon under K04 boost. Silicone now while the front is open."}, {"name": "Thermostat and coolant temp sensor", "why": "Coolant is out on the OE route. Both are FSI weak spots.", "only": ["stock"]}, {"name": "Radiator and condenser fin comb", "why": "Fifteen years of stone damage; straighten the fins while both are on the bench.", "only": ["stock"]}, {"name": "Headlight-washer pump hose clip and fog light connectors", "why": "They break coming off; have them in the box."}], "check": {"tab": "Which style?", "title": "Which intercooler suits the car?", "illId": "intercooler-temps", "illCap": "Both upgraded curves beat stock; the choice is access vs airflow.", "rows": [{"see": "Stock or Stage 1, daily driver, wants factory look", "means": "OE-location core covers it with headroom.", "do": "APR, IE or CTS direct fit; no pipes needed yet."}, {"see": "Stage 2 or K04, hot climate, repeated pulls", "means": "Heat soak is your limit.", "do": "Either style; front-mount wins on outlet temp, OE-location on radiator airflow."}, {"see": "Original FSI pancake pipe, cracked or weeping at the DV", "means": "Pipe is a repair, not a mod.", "do": "Take the 'with charge pipes' kit."}, {"see": "Wants to keep the factory core and reversibility", "means": "Series second core.", "do": "Forge Twintercooler."}, {"see": "No lift, one afternoon, no coolant mess", "means": "Front-mount is the shorter job.", "do": "ECS or Eurojet kit, factory core left in place."}], "c": {"level": "community", "n": 4, "note": "Trade-offs from vendor documentation and owner reports; no independent bake-off between kits."}}, "aftercare": ["Recheck every clamp after the first drive and after the first hot week.", "Log IAT on three pulls a month into summer; if the third pull climbs again, look for a leak, not a bigger core.", "OE route: coolant level cold for a week."], "disagreements": [{"topic": "OE-location vs front-mount", "pos": "Front-mount vendors cite the coolest outlet temps and easy access; OE-location vendors cite radiator airflow and total core volume; one front-mount vendor admits a slight pressure drop and less core than stock.", "call": "Both are big improvements over the sandwich core. OE-location for a clean, radiator-friendly build; front-mount for hot climates and serviceability."}, {"topic": "Leave the factory core in on a front-mount", "pos": "Kits are designed around leaving it; some owners pull it for airflow.", "call": "Leave it unless the radiator is out anyway."}, {"topic": "Power claims", "pos": "Vendors quote 5–15 whp; the honest gain is the timing the tune stops pulling on hot pulls.", "call": "Buy it for repeatability, not the peak number."}], "sources": ["Integrated Engineering IETPCB1 Mk5/Mk6 FDS intercooler install guide (procedure, hardware)", "APR Intercooler System PQ35 page (core spec, five-pull heat-soak test)", "ECS Tuning Mk5 GTI/Jetta FMIC kit pages, with and without charge pipes (dimensions, dyno claims, noise-pipe note)", "IE FDS intercooler product listing (fitment, hose notes)", "golfmk6 owner thread on front-mount vs OE-location (Twintercooler experience)"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();

-- 2. Diverter valve: second question (factory / drop-in electronic / Forge), aliases
insert into guides (id,content) values ('diverter-valve',$j${"id": "diverter-valve", "title": "Diverter valve replacement", "fits": "2006–2009 VW GTI · 2.0T FSI & TSI", "heroId": "dv-hero", "alsoFits": "Every 2.0T FSI/TSI with the K03 turbo (Mk5/Mk6 GTI, Jetta, A3, CC, Tiguan)", "category": "Engine", "kind": "repair", "variants": {"questions": [{"question": "Which engine?", "hint": "Same job, different part number.", "options": [{"id": "fsi", "label": "2.0T FSI (2006–2008.5)", "when": "Original diaphragm valve; replace with the piston-type revision"}, {"id": "tsi", "label": "2.0T TSI (2008.5–2009)", "when": "Early cars have the diaphragm valve; rev D is the fix"}]}, {"question": "Which valve?", "hint": "The factory piston valve is the right fix for a stock or Stage 1–2 car. Aftermarket valves split two ways: drop-in electronic units that keep the VW solenoid (GFB DV+, Turbosmart Kompact EM) and mechanical piston valves that need a vacuum line to the intake manifold (Forge).", "options": [{"id": "oe", "label": "Factory piston valve (VW)", "when": "Stock, Stage 1 or Stage 2. Cheapest, no fitting nuances."}, {"id": "dvplus", "label": "Drop-in electronic (GFB DV+, Turbosmart EM)", "when": "Tuned car, K04, or a factory piston valve that still leaks. Same three bolts; keeps the solenoid."}, {"id": "forge", "label": "Mechanical piston (Forge FMFSITVR)", "when": "Big-turbo or you want spring-adjustable behaviour. Adds a vacuum line and a solenoid bracket."}]}]}, "glance": {"timeFirst": "30 min", "timeRepeat": "15 min", "difficulty": 1.5, "cost": "$60–120", "risk": "Three bolts in an awkward spot; hot turbo", "why": "The diverter valve sits on the turbo and dumps boost back to the inlet when you lift off the throttle. The early one has a rubber diaphragm that tears, and then the turbo can't hold boost: soft power, a code, sometimes a flutter. VW's fix was a piston-type valve, and fitting it is three bolts.", "note": "Vendor sheets (Forge kit instructions, GFB and Turbosmart listings) and owner threads agree on parts; the only variable is reaching the bolts."}, "heroCap": "Three Torx bolts hold the valve to the turbo's compressor housing. Unplug, unbolt, swap, done.", "lifespan": {"title": "When to expect it", "headline": ["Original diaphragm valves commonly fail by 60,000–100,000 miles; sooner with a tune"], "earliest": "20k on tuned cars", "detail": "Symptoms: boost that builds then falls away, a code for underboost or a DV circuit fault, and sometimes a fluttering noise on lift-off. Tuned cars kill diaphragm valves fast because they run more pressure across them.", "factors": ["Tune", "Age of the rubber", "Heat"], "inspect": ["Any underboost code: pull the valve and look at the diaphragm"], "confidence": {"level": "community", "n": 4, "note": "Vendor articles and forum consensus."}}, "should": {"yesIf": ["Underboost codes (P0299) or DV codes (P0033, P0034)", "Boost builds then drops", "Fluttering on lift-off", "You've tuned it and still have the diaphragm valve"], "codes": ["P0299", "P0033", "P0034"], "notes": [{"text": "FSI part: the piston-type revision (06F 145 710 G) replaces the original diaphragm valves. Any 'D' rev TSI valve also physically fits and many owners use it.", "only": ["fsi"]}, {"text": "TSI part: 06H 145 710 D is the piston-type revision that replaces the earlier diaphragm valves (A, B, C). Buy D.", "only": ["tsi"]}, {"only": ["dvplus"], "text": "GFB DV+ (T9351) and Turbosmart Kompact EM keep the VW solenoid coil and replace only the valve mechanism with a billet body and sealed piston. Plug-and-play, no vacuum lines, no codes. The DV+ needs two minutes of assembly onto your solenoid; the Turbosmart is one piece."}, {"only": ["forge"], "text": "Forge FMFSITVR is a pressure/vacuum piston valve that mounts where the VW valve was and takes its vacuum reference from an intake-manifold tap included in the kit. The VW solenoid stays plugged in on a bracket so the ECU sees no fault. Longer install; the payoff is spring-adjustable behaviour at high boost."}], "confidence": {"level": "high", "n": 4, "note": "Part revisions and procedure consistent across DAP, ECS and forum threads."}}, "parts": [{"tier": "oe", "name": "Diverter valve, piston type", "pn": "06F 145 710 G", "note": "FSI", "price": "$60–90", "links": [], "only": ["fsi+oe"]}, {"tier": "oe", "name": "Diverter valve, revision D", "pn": "06H 145 710 D", "note": "TSI", "price": "$60–90", "links": [], "only": ["tsi+oe"]}, {"tier": "aftermarket", "name": "GFB DV+", "pn": "T9351", "note": "Billet body, brass piston; reuses your solenoid", "price": "$140–170", "links": [{"store": "UroTuning", "url": "https://www.urotuning.com/products/gfb-dv-diverter-valve-1-8t-2-0t-fsi-tsi-t9351"}], "only": ["dvplus"]}, {"tier": "aftermarket", "name": "Turbosmart Kompact EM plumb-back", "pn": "TS-0223-1263", "note": "One-piece electronic; direct swap", "price": "$200–250", "links": [], "only": ["dvplus"]}, {"tier": "aftermarket", "name": "Forge FMFSITVR replacement valve kit", "pn": "FMFSITVR", "note": "Valve, manifold tap, hose, solenoid bracket, springs", "price": "$200–260", "links": [{"store": "USP Motorsports", "url": "https://www.uspmotorsports.com/product/forge-diverter-valve-for-20t-black-75004707"}], "only": ["forge"]}, {"tier": "oe", "name": "O-ring for the valve flange", "pn": "in the box / N 906 254 01 style", "note": "Never reuse", "price": "$3", "links": []}], "aftermarket": [{"name": "GFB DV+ / Turbosmart Kompact EM", "note": "Fix the leak, keep the ECU's timing. The sensible upgrade for any tuned car; the factory piston valve leaks a little by design and can hang open after a hard shift.", "price": "$140–250", "signal": "Tuned cars", "links": []}, {"name": "Forge FMFSITVR", "note": "Mechanical piston with interchangeable springs. Slower to actuate than the ECU-driven valves, but adjustable and unbothered by 30 psi.", "price": "$200–260", "signal": "Big turbo", "links": []}, {"name": "Blow-off (vent-to-atmosphere) valves", "note": "Sound, at the cost of a rich stumble between shifts on a MAF car. Not recommended on the FSI.", "price": "$200–300", "signal": "Sound only", "links": []}], "tools": [{"name": "T30 Torx on a ¼\" ratchet with a wobble extension; a mirror"}, {"name": "Flat screwdriver for the connector lock"}, {"name": "5 mm hex for the Forge valve and bracket; hose cutter; a drill or step bit only if your manifold tap needs it (see the kit sheet)", "only": ["forge"]}], "before": ["Engine cold; the valve is on the turbo.", "Look at the new valve first so you know what you're feeling for: three bolt holes in a triangle and one connector."], "steps": [{"n": 1, "title": "Find it", "blocks": [{"t": "text", "b": "On the compressor (cold) side of the turbo, at the back of the engine on the driver's side: a round black valve with an electrical connector, held by three Torx bolts. Engine cover off; on some cars pulling the inlet pipe gives the room you need."}, {"t": "ill", "id": "dv-hero", "cap": "Three bolts in a triangle. The lower one is the awkward one."}]}, {"n": 2, "title": "Unplug and unbolt", "blocks": [{"t": "text", "b": "Slide the connector lock and unplug. Three T30 bolts; the bottom one usually needs the wobble extension and patience. Lift the valve out; note the o-ring."}]}, {"n": 3, "title": "Look at the old one", "blocks": [{"t": "text", "b": "A diaphragm valve shows a rubber disc; if it's torn or holed, that was your problem. A piston valve is the revision already; if it looks fine, your underboost is elsewhere (PCV, a split hose, the wastegate)."}]}, {"n": 4, "title": "Assemble the DV+ onto your solenoid", "only": ["dvplus"], "blocks": [{"t": "text", "b": "GFB's kit replaces the valve half. Pull the old plastic piston and spring off the solenoid body, fit the GFB body, brass piston and spring in the order the sheet shows, and seat the new o-ring. Turbosmart's Kompact EM skips this: it's a complete unit that plugs into your harness."}, {"t": "note", "b": "Keep the VW coil. It's the part that isn't broken and the ECU actuates it faster than any pneumatic valve could."}]}, {"n": 4, "title": "Fit the vacuum tap and bracket", "only": ["forge"], "blocks": [{"t": "text", "b": "The Forge valve needs a manifold reference. Fit the kit's tap to the intake manifold vacuum port it specifies (the tap has two spare ports for a boost gauge or meth trigger), run the hose to the valve's top port, and route it away from the passenger axle. Bolt the solenoid to the kit bracket on one of the valve's mounting holes and leave it plugged in; that's what keeps the fault codes away."}, {"t": "warn", "b": "Any hose near the axle or the turbo heat shield gets zip-tied clear. A chafed vacuum line is a valve that never opens."}]}, {"n": 5, "title": "New valve in", "blocks": [{"t": "text", "b": "New o-ring seated, valve in the same orientation, three bolts snug in turn (about 8 Nm; small bolts into aluminium). Connector on until it clicks. Forge: reuse the VW bolts with the bracket under one of them, then snug. Cover on."}, {"t": "torque", "label": "Diverter valve bolts (T30 ×3)", "nm": 8, "c": {"level": "single", "n": 1, "note": "Snug figure from kit sheets; no factory value confirmed this pass."}}]}, {"n": 6, "title": "Drive it", "blocks": [{"t": "text", "b": "Clear codes if you had them. Boost should hold to redline and the flutter should be gone."}]}], "alsoReplace": [{"name": "PCV valve", "why": "The other diaphragm on this engine, with overlapping symptoms. If one is original, the other is too."}, {"name": "Turbo inlet coupler and charge hoses", "why": "Split rubber is the other cause of underboost. Squeeze them while you're there."}], "check": {"tab": "Is it the DV?", "title": "Is the diverter valve the problem?", "illId": "dv-hero", "illCap": "Torn diaphragm settles it.", "rows": [{"see": "P0299 underboost, boost falls off", "means": "DV, PCV, or a leak.", "do": "DV first if it's the diaphragm type; it's cheap."}, {"see": "Flutter on lift-off", "means": "DV not sealing or opening late.", "do": "Replace."}, {"see": "Piston DV already fitted, still underboost", "means": "Not the DV.", "do": "PCV, charge hoses, wastegate actuator."}], "c": {"level": "community", "n": 3, "note": "Forum diagnosis and vendor articles."}}, "aftercare": ["None. If the code returns, move down the list above."], "disagreements": [{"topic": "Factory piston valve vs aftermarket", "pos": "Owners split: 'rev D and done' vs 'the piston valve leaks by design'. Vendors of both electronic drop-ins and mechanical valves claim sharper response.", "call": "Factory piston valve on stock and Stage 1–2. DV+ or Kompact on K04 and above, or when a piston valve car still shows soft boost after a shift. Forge mechanical only for big-turbo builds."}, {"topic": "Blow-off valves", "pos": "Sound good; MAF-metered engines run rich for a moment on each shift.", "call": "Not on the FSI."}], "sources": ["DAP 2.0T TSI common problems (DV section)", "ECS / vendor DV listings and revision notes", "Forum threads on DV symptoms and revisions", "Forge Motorsport 2.0T FSI replacement bypass valve kit instructions (ECS PDF)", "GFB DV+ T9351 and Turbosmart Kompact EM listings", "Audizine diverter valve information threads (piston valve leak-by-design, electronic vs pneumatic actuation)"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into tasks (id,powertrain_id,guide_id,title,category,group_name,aliases,live,time_label,difficulty) values ('diverter-valve','bpy','diverter-valve','Diverter valve replacement','Engine',null,array['blow off valve','boost leak','bov','diverter valve','dv','dv+','forge dv','gfb','p0299','underboost']::text[],true,'30 min',1.5) on conflict (id) do update set powertrain_id=excluded.powertrain_id, guide_id=excluded.guide_id, title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into tasks (id,powertrain_id,guide_id,title,category,group_name,aliases,live,time_label,difficulty) values ('diverter-valve-tsi','ccta','diverter-valve','Diverter valve replacement','Engine',null,array['blow off valve','boost leak','bov','diverter valve','dv','dv+','forge dv','gfb','p0299','underboost']::text[],true,'30 min',1.5) on conflict (id) do update set powertrain_id=excluded.powertrain_id, guide_id=excluded.guide_id, title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;

-- 3. Headlights move to Exterior on every engine
update tasks set category='Exterior' where guide_id='headlights';
